  # Every ability used above (plus earlier ones kept so ER_ONLY positions stay stable).
  # :pif => true if PIF already has an ability with this id.
  ABILITY_TEXT = {
    :STENCH => { :name => "Stench", :pif => true, :short => "10% chance to flinch targets. Toxic terrain is permanent.", :full => "Attacks gain +10% flinch chance. Chance is rolled separately on multi-hit attacks. Toxic Terrain turns do not decrease while the user is present." },
    :DRIZZLE => { :name => "Drizzle", :pif => true, :short => "Summons rain on entry. Lasts 8 turns.", :full => "Drizzle summons rain weather when the Pokemon enters battle, lasting 8 turns (12 with Damp Rock held). Rain boosts Water moves by 50% and cuts Fire damage by 50%. Certain moves and abilities have special interactions with rain. Cannot override primal weather conditions." },
    :SPEEDBOOST => { :name => "Speed Boost", :pif => true, :short => "Raises own Speed by one stage after every turn.", :full => "User's Speed increases by one stage at end of each full turn they remain on the field. Doesn't activate on the turn the user is switched in." },
    :BATTLEARMOR => { :name => "Battle Armor", :pif => true, :short => "Immune to critical hits. Takes 20% less damage from attacks.", :full => "Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed." },
    :STURDY => { :name => "Sturdy", :pif => true, :short => "At full HP, cannot be KO in one hit, stays at 1 HP instead.", :full => "When at full HP, this Pokemon will survive any single attack with at least 1 HP remaining. This functions like a Focus Sash, and so does not protect against multihit attacks or follow-up attacks (e.g. Aftershock, Thundercall)." },
    :DAMP => { :name => "Damp", :pif => true, :short => "Makes foe Water-type on contact. Also works on offense.", :full => "If the user makes contact with another Pokemon, offensively or defensively, the other Pokemon's type is changed to pure Water. This happens immediately for multihit or priority moves and can remove STAB in the middle of an enemy's multihit move." },
    :LIMBER => { :name => "Limber", :pif => true, :short => "Paralysis immune, halves recoil damage, negates self stat drop.", :full => "All recoil damage to the user is halved; this includes moves with scaling recoil damage like Brave Bird, moves with crash damage like Jump Kick, or moves with fixed recoil like Steel Beam. Paralysis also cannot affect the user, and if they gain Limber, existing paralysis is cured." },
    :SANDVEIL => { :name => "Sand Veil", :pif => true, :short => "Evasion is boosted by 1.25x while a sandstorm is active.", :full => "During sandstorm, enemy Pokemon's accuracy is divided by 1.25, and user is immune to sand damage. Bypassed by No Guard/Mold Breaker." },
    :STATIC => { :name => "Static", :pif => true, :short => "30% chance to paralyze on contact, 10% on non-contact.", :full => "Has a chance to paralyze when attacking or when hit by a move. Has a 10% chance to paralyze on non-contact attacks and a 30% chance to paralyze on contact attacks." },
    :VOLTABSORB => { :name => "Volt Absorb", :pif => true, :short => "Heals 25% of max HP when hit by an Electric-type move.", :full => "This Pokemon absorbs Electric-type moves completely, converting them into energy that restores 25% of its maximum HP. Provides complete immunity to Electric damage and effects like paralysis from Thunder Wave. Absolutely perfect for Water/Flying types to remove their 4x Electric weakness." },
    :WATERABSORB => { :name => "Water Absorb", :pif => true, :short => "Heals 25% of max HP when hit by a Water-type move.", :full => "The user gains immunity to Water-type moves and they heal for 25% of their max HP when hit by them." },
    :OBLIVIOUS => { :name => "Oblivious", :pif => true, :short => "Immune to infatuation, Scare, Intimidate and disabling.", :full => "This Pokemon is immune to infatuation, Scare, Intimidate and disabling effects (Taunt, Disable, Encore, and Torment). When gaining this ability while afflicted by any of the mentioned statuses, instantly cures them." },
    :CLOUDNINE => { :name => "Cloud Nine", :pif => true, :short => "Clears weather and prevents its effects.", :full => "Cloud Nine clears all weather upon switch-in and nullifies weather effects (including Primal weathers) while the user remains on the field. Weather can still be set, but provides no damage boosts or ability triggers until the user switches out." },
    :COMPOUNDEYES => { :name => "Compound Eyes", :pif => true, :short => "Grants a 1.3x accuracy boost.", :full => "Boosts the user's accuracy by 1.3x." },
    :INSOMNIA => { :name => "Insomnia", :pif => true, :short => "Cannot fall asleep. Rest fails if used.", :full => "Prevents falling asleep by any means, including sleep moves, abilities like Yawn, and other effects that cause sleep status. Rest will fail completely when used. If gained while asleep (via Worry Seed/Skill Swap), immediately wakes up. Can be bypassed by Mold Breaker and similar abilities. TEST" },
    :COLORCHANGE => { :name => "Color Change", :pif => true, :short => "Changes type to a resist or an immunity before getting hit.", :full => "Transforms the user into the best defensive type before taking damage. Prioritizes immunities over resistances. Only changes to a pure type. Once per turn." },
    :IMMUNITY => { :name => "Immunity", :pif => true, :short => "Cannot be poisoned. Halves damage taken from Poison moves.", :full => "Prevents poisoning. Reduces all Poison-type damage by 50%. Multiplicative with other sources of damage reduction. If poisoned when gaining this ability, the poison is immediately cured." },
    :FLASHFIRE => { :name => "Flash Fire", :pif => true, :short => "Powers up Fire-type moves by 1.5x if hit by a Fire-type move.", :full => "Flash Fire grants complete immunity to Fire-type moves. When hit by Fire attacks, powers up the user's Fire moves by 50% until switching out. The boost doesn't stack from multiple Fire hits." },
    :SHIELDDUST => { :name => "Shield Dust", :pif => true, :short => "Immune to added move effects, hazards, and powder moves.", :full => "Blocks all secondary effects from damaging moves. Grants immunity to entry hazards. Blocks all powder moves including Sleep Powder, Stun Spore, Poison Powder, Spore, Cotton Spore, Rage Powder, Powder, and Magic Powder." },
    :OWNTEMPO => { :name => "Own Tempo", :pif => true, :short => "Immune to confusion, Intimidate and Scare.", :full => "Grants immunity to confusion, Intimidate, and Scare. Immediately cures confusion when receiving this ability." },
    :SUCTIONCUPS => { :name => "Suction Cups", :pif => true, :short => "Cannot be forced to switch out by an enemy's move.", :full => "Prevents forced switching from moves and Red Card." },
    :INTIMIDATE => { :name => "Intimidate", :pif => true, :short => "Lowers foes' Atk by one stage on entry.", :full => "Upon entering battle, the user drops the Attack stat of all opposing Pokemon by one stage." },
    :SHADOWTAG => { :name => "Shadow Tag", :pif => true, :short => "Opponents can't be switched out. Ghosts aren't affected.", :full => "Prevents all non-Shadow Tag or Ghost-type foes from switching out. Pokemon holding Shed Shell or using a pivot move such as Flip Turn can escape. Activates during the next turn if the user switches in mid battle." },
    :ROUGHSKIN => { :name => "Rough Skin", :pif => true, :short => "Enemies lose 1/8 of max HP if they hit user with contact move.", :full => "Damages attackers using contact moves for 1/8 of their max HP. Activates on every hit for multihitting moves." },
    :WONDERGUARD => { :name => "Wonder Guard", :pif => true, :short => "Is only hit by Super-effective attacks or indirect damage.", :full => "Only super-effective attacks or indirect damage can hurt the user. All other direct attacks deal zero damage. Other sources such as poison or ability damage still function as normal." },
    :LEVITATE => { :name => "Levitate", :pif => true, :short => "Immune to Ground-type moves. Ups own Flying moves by 1.25x.", :full => "The user is immune to Ground-type moves and other ground effects such as Spikes and terrains. Boosts the damage of Flying-type moves by 25%." },
    :EFFECTSPORE => { :name => "Effect Spore", :pif => true, :short => "30% chance to inflict SLP, PARA or PSN if hit by a contact move.", :full => "When hit by a contact move, 30% chance to inflict sleep, paralysis, or poison. Chosen randomly." },
    :CLEARBODY => { :name => "Clear Body", :pif => true, :short => "Immune to stat drops.", :full => "Gives immunity to all stat reductions from moves and abilities. Includes self stat drops from moves like Overheat." },
    :NATURALCURE => { :name => "Natural Cure", :pif => true, :short => "Heals status condition upon switching out.", :full => "Cures all status conditions when switching out." },
    :LIGHTNINGROD => { :name => "Lightning Rod", :pif => true, :short => "Redirects Electric moves. Absorbs them, ups highest Atk.", :full => "The user draws in Electric-type moves and gains immunity to them. Additionally, Electric-type moves boost the highest attacking stat of the user by one stage." },
    :SERENEGRACE => { :name => "Serene Grace", :pif => true, :short => "Doubles chance of secondary effects on its own moves.", :full => "Doubles the activation chance of the user's secondary effects on their attacks." },
    :SWIFTSWIM => { :name => "Swift Swim", :pif => true, :short => "This Pokémon's Speed gets a 1.5x boost if rain is active.", :full => "Boosts Speed by 50% during rain." },
    :CHLOROPHYLL => { :name => "Chlorophyll", :pif => true, :short => "This Pokémon's Speed gets a 1.5x boost if sun is active.", :full => "Boosts the Pokemon's Speed by 50% during sun." },
    :ILLUMINATE => { :name => "Illuminate", :pif => true, :short => "1.2x accuracy. Attacks remove Ghost-type from target.", :full => "Boosts the user's accuracy by 1.2x. Removes Ghost-type from the target when landing an attack." },
    :TRACE => { :name => "Trace", :pif => true, :short => "Copies the foe's ability. Does not copy innates.", :full => "Copies the ability of an opposing Pokemon when entering battle, replacing itself in the current ability slot. Cannot copy Trace, Wonder Guard, and most form related abilities. In doubles, targets the first valid opponent at random." },
    :HUGEPOWER => { :name => "Huge Power", :pif => true, :short => "Doubles own Attack stat. Boosts raw stat, not base stat.", :full => "Increases the user's Attack stat by 2x. Multiplicative with other damage boosts." },
    :POISONPOINT => { :name => "Poison Point", :pif => true, :short => "30% chance to poison on contact. Also works on offense.", :full => "Has a 30% chance to inflict poison on contact moves, both when attacking and being attacked." },
    :INNERFOCUS => { :name => "Inner Focus", :pif => true, :short => "Blocks flinch, Intimidate, Scare. Focus Blast never misses.", :full => "Focus Blast never misses. Unaffected by flinch, Intimidate, or Scare." },
    :MAGMAARMOR => { :name => "Magma Armor", :pif => true, :short => "Frostbite-immune. Takes 30% less dmg from Water/Ice-type moves.", :full => "Immune to frostbite. Reduces damage received from Water and Ice-type moves by 30%. Multiplicative with other sources of damage reduction." },
    :WATERVEIL => { :name => "Water Veil", :pif => true, :short => "Burn-immune. Casts Aqua Ring on entry.", :full => "Uses Aqua Ring on entry, which restores 1/16 HP each turn. Grants immunity to burn status and removes burn on switching in." },
    :MAGNETPULL => { :name => "Magnet Pull", :pif => true, :short => "Traps opposing Steel-types. Ghosts aren't affected.", :full => "Prevents Steel-type Pokemon from switching out while the user is present. Ghost-types are immune to this effect. Pokemon holding Shed Shell or using a pivot move such as Flip Turn can escape. Activates during the next turn if the user switches in mid battle." },
    :SOUNDPROOF => { :name => "Soundproof", :pif => true, :short => "Immune to sound-based moves.", :full => "Grants immunity to sound-based moves. Self-targeting sound moves are not blocked." },
    :RAINDISH => { :name => "Rain Dish", :pif => true, :short => "Heals 1/8 of max HP every turn if rain is active.", :full => "Restores 1/8 max HP at the end of each turn in rain." },
    :SANDSTREAM => { :name => "Sand Stream", :pif => true, :short => "Summons a sandstorm on entry. Lasts 8 turns.", :full => "Summons a Sandstorm for 8 turns (12 with Smooth Rock) on entry. Damages non-Rock/Ground/Steel types by 1/16 HP per turn. Rock-types gain a 50% Special Defense boost. Halves the effectiveness of sun related moves." },
    :PRESSURE => { :name => "Pressure", :pif => true, :short => "Doubles foe's PP usage. Clears stat buffs on entry.", :full => "Doubles PP usage of opposing moves and clears all positive stat stages on entry." },
    :THICKFAT => { :name => "Thick Fat", :pif => true, :short => "Takes 1/2 damage from Fire-type and Ice-type attacks.", :full => "Reduces damage received from Fire and Ice-type moves by 50%. Multiplicative with other sources of damage reduction." },
    :EARLYBIRD => { :name => "Early Bird", :pif => true, :short => "Awakens twice as fast from sleep.", :full => "Allows the user to wake up from sleep twice as fast. Subtract 2 sleep turns every turn instead of 1." },
    :FLAMEBODY => { :name => "Flame Body", :pif => true, :short => "30% chance to burn on contact, 20% non. Also works on offense.", :full => "Contact with this Pokemon has a 30% chance to inflict burn. Non-contact has a 20% chance. Works offensively and defensively." },
    :RUNAWAY => { :name => "Run Away", :pif => true, :short => "Guarantees fleeing. Raises Speed if stats lowered by an enemy.", :full => "Guarantees successful escape from wild Pokemon battles regardless of speed differences. When any of the user's stats are lowered by an opponent's move or ability, raises the user's Speed by 2 stages." },
    :KEENEYE => { :name => "Keen Eye", :pif => true, :short => "Immune to accuracy drops. Grants a 1.2x accuracy boost.", :full => "Prevents accuracy stat stage drops. All moves gain a 1.2x accuracy boost." },
    :HYPERCUTTER => { :name => "Hyper Cutter", :pif => true, :short => "Enemies can't lower Atk/SpAtk. Contact moves get +1 Crit.", :full => "Hyper Cutter prevents enemies from lowering the user's Attack stat through moves or abilities. All contact moves used by this Pokemon have their critical hit rate increased by one stage." },
    :PICKUP => { :name => "Pickup", :pif => true, :short => "Removes all hazards on entry. Not immune to hazards.", :full => "Clears all entry hazards from your side of the field when entering battle. The Pokemon is still susceptible to hazards while clearing them." },
    :TRUANT => { :name => "Truant", :pif => true, :short => "Can't use attacking moves twice in a row.", :full => "Prevents consecutive attacking moves. After using an attack, the user must loaf around next turn and cannot attack. Status moves remain unaffected." },
    :HUSTLE => { :name => "Hustle", :pif => true, :short => "0.9x accuracy. Boosts damage by 1.4x.", :full => "Boosts the power of attacks by 1.4x but reduces their accuracy by 10%. Only affects non-status moves." },
    :CUTECHARM => { :name => "Cute Charm", :pif => true, :short => "50% chance to infatuate on contact. Also works on offense.", :full => "When hit by making contact (offensively or defensively), has a 50% chance to infatuate the attacker (cuts their Attack and Special Attack in half)." },
    :PLUS => { :name => "Plus", :pif => true, :short => "Deals double damage if an ally Pokémon has Minus or Plus.", :full => "Doubles the Pokemon's offensive power when partnered with an ally that has Plus or Minus." },
    :MINUS => { :name => "Minus", :pif => true, :short => "Deals double damage if an ally Pokémon has Minus or Plus.", :full => "Doubles the Pokemon's offensive power when partnered with an ally that has Minus or Plus." },
    :FORECAST => { :name => "Forecast", :pif => true, :short => "Changes form with the weather. Attacks when setting weather.", :full => "Changes form and type to match active weather. When using weather setting moves, follows up with Weather Ball (100 BP, Special, matching type with set weather). Transforms on entry, weather changes, and turn end. Unsuppressable ability that works even under Mold Breaker effects." },
    :STICKYHOLD => { :name => "Sticky Hold", :pif => true, :short => "Can't lose its item.", :full => "The user's item cannot be forcibly removed or stolen." },
    :SHEDSKIN => { :name => "Shed Skin", :pif => true, :short => "30% chance to heal its status condition at the end of a turn.", :full => "At the end of each turn, there's a 30% chance for the user to cure status conditions afflicted on them." },
    :GUTS => { :name => "Guts", :pif => true, :short => "Ups Attack by 1.5x if statused.", :full => "Boosts Attack stat by 50% when suffering from any status condition. Negates the Attack drop from burn status." },
    :MARVELSCALE => { :name => "Marvel Scale", :pif => true, :short => "Ups Defense by 1.5x when statused.", :full => "Increases base Defense by 50% when afflicted with any status condition." },
    :LIQUIDOOZE => { :name => "Liquid Ooze", :pif => true, :short => "Draining causes harm to enemies instead of healing them.", :full => "Liquid Ooze reverses all healing effects from drain moves, causing the attacker to take damage instead. Affects Absorb, Drain Punch, Giga Drain, Leech Life, and similar draining attacks. The damage equals what would have been healed. Perfect counter to healing-based strategies." },
    :OVERGROW => { :name => "Overgrow", :pif => true, :short => "Boosts Grass-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Grass-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :BLAZE => { :name => "Blaze", :pif => true, :short => "Boosts Fire-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Fire-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :TORRENT => { :name => "Torrent", :pif => true, :short => "Boosts Water-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Water-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :SWARM => { :name => "Swarm", :pif => true, :short => "Boosts Bug-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Bug-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :ROCKHEAD => { :name => "Rock Head", :pif => true, :short => "Immune to recoil damage, but not immune to Explosion/crash dmg.", :full => "Prevents all recoil damage from the user's moves and abilities. Also grants immunity to enrage recoil damage. Does not prevent crash damage or Explosion/Self-Destruct damage." },
    :DROUGHT => { :name => "Drought", :pif => true, :short => "Summons sun on entry. Lasts 8 turns.", :full => "Summons harsh sunlight for 8 turns (12 with Heat Rock) on entry. Boosts Fire moves by 50%, reduces Water moves by 50%. Activates extra effects on sun related moves." },
    :ARENATRAP => { :name => "Arena Trap", :pif => true, :short => "Enemies can't flee. Ghosts and ungrounded Pokémon are immune.", :full => "Prevents all non-levitating or Ghost-type foes from switching out. Pokemon holding Shed Shell or using a pivot move such as Flip Turn can escape. Activates during the next turn if the user switches in mid battle" },
    :VITALSPIRIT => { :name => "Vital Spirit", :pif => true, :short => "Can't fall asleep. Fighting-type moves heal status.", :full => "Immune to sleep. When the Pokemon uses a Fighting-type move, it heals all status conditions immediately after the move resolves. Removes sleep when gained." },
    :WHITESMOKE => { :name => "White Smoke", :pif => true, :short => "Sets Smokescreen for 3 turns on switch-in.", :full => "Sets Smokescreen on entry, lasting 3 turns. Smokescreen increases the evasiveness of your party by 25%." },
    :SHELLARMOR => { :name => "Shell Armor", :pif => true, :short => "Immune to critical hits. Takes 20% less damage from attacks.", :full => "Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed." },
    :AIRLOCK => { :name => "Air Lock", :pif => true, :short => "Cloud Nine + Air Blower.", :full => "Sets Tailwind for 3 turns and clears all weather effects on entry. Primal weathers are suppressed. Weather can still be set while the user is on the field, but will have no effect until the user switches." },
    :MOTORDRIVE => { :name => "Motor Drive", :pif => true, :short => "Boosts Speed instead of being hit by Electric-type moves.", :full => "Immune to Electric-type moves, and boost Speed by 1 stage when the user is hit by them. Activates on each hit of a multihit move." },
    :RIVALRY => { :name => "Rivalry", :pif => true, :short => "Deals 1.25x to same gender. Takes .75x from opposite gender.", :full => "Boosts the user's damage by 25% against same-gender Pokemon and reduces damage taken by 25% from opposite-gender Pokemon. No effect with genderless Pokemon." },
    :STEADFAST => { :name => "Steadfast", :pif => true, :short => "Raises Speed by one stage if this Pokémon flinches.", :full => "Getting flinched raises Speed by one stage." },
    :SNOWCLOAK => { :name => "Snow Cloak", :pif => true, :short => "Evasion is boosted by 1.25x under hail.", :full => "Evasion is boosted by 1.25x under hail." },
    :GLUTTONY => { :name => "Gluttony", :pif => true, :short => "Eats berries early. Berries also restore 1/3 of max HP.", :full => "Berries that normally activate at 1/4 HP trigger at 1/2 HP instead. Additionally, after consuming any berry, the user recovers 1/3 of max HP. Does not include berries consumed through moves like Pluck." },
    :ANGERPOINT => { :name => "Anger Point", :pif => true, :short => "Getting hit raises Atk by +1. Critical hits maximize Attack.", :full => "When hit, raises the user's Attack by 1 stage or maximizes it on critical hits. Activates on each hit of a multihit move." },
    :UNBURDEN => { :name => "Unburden", :pif => true, :short => "Consuming its held item doubles Speed until switched out.", :full => "When consuming or losing a held item, the user's base Speed stat is multiplied by x2. Boost goes away when switching out, gaining a new item, or upon losing the ability." },
    :HEATPROOF => { :name => "Heatproof", :pif => true, :short => "Halves damage taken from Fire-type moves. Takes no burn damage.", :full => "Halves damage from Fire-type moves. Immune to burn damage and Attack drops from burn status." },
    :SIMPLE => { :name => "Simple", :pif => true, :short => "Doubles all stat changes on this Pokémon.", :full => "Doubles all stat changes on this Pokémon." },
    :DRYSKIN => { :name => "Dry Skin", :pif => true, :short => "Water/Rain heals. Fire/Sun hurts.", :full => "The user heals 25% HP from Water-type moves and 12.5% HP each turn in rain. Takes 25% more damage from Fire moves and loses 12.5% HP per turn in sun." },
    :DOWNLOAD => { :name => "Download", :pif => true, :short => "Raises Atk/Sp. Atk by one stage depending on opponent.", :full => "When switching in, if the foe's Defense is higher than Special Defense, raise Special Attack by one stage. If Special Defense is higher or equal, raise Attack by one stage." },
    :IRONFIST => { :name => "Iron Fist", :pif => true, :short => "Boosts the power of punching moves by 1.3x.", :full => "Boosts the power of punching moves by 30%." },
    :POISONHEAL => { :name => "Poison Heal", :pif => true, :short => "Restores 1/8 of max HP after each turn if poisoned.", :full => "Restores 1/8 max HP per turn instead of taking damage when poisoned. Works with both regular poison and toxic poison. Also prevents damage from Toxic terrain." },
    :ADAPTABILITY => { :name => "Adaptability", :pif => true, :short => "Increases STAB from 1.5x to 2x.", :full => "Boosts STAB damage boost on moves from 1.5x to 2.0x damage." },
    :SKILLLINK => { :name => "Skill Link", :pif => true, :short => "Multi-hit moves always hit the maximum number of times.", :full => "Multihit moves to always hit 5 times. For moves that only hit 3 times or Population Bomb, there will be one accuracy check for all hits instead of individual checks for each hit." },
    :HYDRATION => { :name => "Hydration", :pif => true, :short => "Cures own status at the end of every turn in rain.", :full => "During rain, cures all status conditions at the end of the turn." },
    :SOLARPOWER => { :name => "Solar Power", :pif => true, :short => "Ups highest attacking stat by 1.5x in sun.", :full => "Boosts the Pokemon's highest attacking stat by 50% during sun." },
    :QUICKFEET => { :name => "Quick Feet", :pif => true, :short => "Ups Speed by 1.5x if suffering from a status condition.", :full => "Boosts Speed stat by 50% when suffering from any status condition. Negates the Speed drop from paralysis status." },
    :NORMALIZE => { :name => "Normalize", :pif => true, :short => "Its moves become Normal-type, get 1.1x boost, ignore resists.", :full => "Converts all damaging moves to Normal-type and grants a 10% power boost. Normal-type moves bypass resistances, but not immunities." },
    :SNIPER => { :name => "Sniper", :pif => true, :short => "Critical hits have a 2.25x dmg multiplier instead of 1.5x.", :full => "Boosts critical hit damage from 1.5x to 2.25x by applying an additional 50% multiplier." },
    :MAGICGUARD => { :name => "Magic Guard", :pif => true, :short => "Only damaged by attacks.", :full => "Grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil." },
    :NOGUARD => { :name => "No Guard", :pif => true, :short => "Attacks used by and on this Pokémon bypass accuracy checks.", :full => "Guarantees hits for all moves used by and against the user." },
    :STALL => { :name => "Stall", :pif => true, :short => "Takes 30% less damage if it hasn't moved yet.", :full => "Reduces damage by 30% if the user has not moved yet. Multiplicative with other damage reduction sources. Works when the user switches in mid-turn." },
    :TECHNICIAN => { :name => "Technician", :pif => true, :short => "Moves with 60 BP or less get a 1.5x boost.", :full => "Boosts moves with 60 BP or less by 1.5x. Does not boost moves with 60 BP or less if they potentially can have more than 60 BP, such as Revenge or Venoshock." },
    :LEAFGUARD => { :name => "Leaf Guard", :pif => true, :short => "Cures own status at the end of every turn in sun.", :full => "During sun, cures all status conditions at the end of the turn." },
    :KLUTZ => { :name => "Klutz", :pif => true, :short => "Own held item has no effect. Mega Stones are unaffected.", :full => "Disables all held item effects. Items can still be knocked off or stolen but give no benefits. Item-based moves like Fling fail. Mega Stones bypass this restriction." },
    :MOLDBREAKER => { :name => "Mold Breaker", :pif => true, :short => "Moves hit through abilities. Also affects innates.", :full => "Allows moves to ignore the target's abilities and innates that interfere with effects or reduce damage. Does not bypass abilities that modify base stats such as Grass Pelt." },
    :SUPERLUCK => { :name => "Super Luck", :pif => true, :short => "Raises critical-hit ratio of own moves by +1.", :full => "Adds +1 to the critical hit stage of all the Pokemon's damaging moves." },
    :AFTERMATH => { :name => "Aftermath", :pif => true, :short => "100BP Explosion / Outburst when KOed. Explosion moves flinch.", :full => "Uses a 100BP Explosion (if Attack is higher) or Outburst (if Special Attack is higher) when knocked out. Using explosion moves will always flinch the target." },
    :ANTICIPATION => { :name => "Anticipation", :pif => true, :short => "Senses Super-effective moves. Dodges one Super-effective hit.", :full => "Alerts the Pokemon when facing opponents with super-effective moves on switch-in. Dodge the first super effective hit received in battle." },
    :FOREWARN => { :name => "Forewarn", :pif => true, :short => "Casts an 80 BP Future Sight on entry.", :full => "Casts an 80 BP Future Sight on the opposing Pokemon when switching in. Strikes 2 turns later, bypassing substitutes and other protections. The attack cannot miss once initiated and ignores accuracy checks. This cannot target the same Pokemon twice." },
    :UNAWARE => { :name => "Unaware", :pif => true, :short => "Ignores foes' stat changes, both positive and negative ones.", :full => "Ignores all the foes' stat stage changes during damage calculations." },
    :TINTEDLENS => { :name => "Tinted Lens", :pif => true, :short => "Attacks deal double damage if resisted.", :full => "Doubles damage when attacking into resistances. If a move would be resisted (0.5x damage or less), the damage is multiplied by 2x." },
    :FILTER => { :name => "Filter", :pif => true, :short => "Takes 35% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 35%. Multiplicative with other sources of damage reduction." },
    :SCRAPPY => { :name => "Scrappy", :pif => true, :short => "Normal/Fighting can hit Ghosts. Immune to Intimidate/Scare.", :full => "The user can land Normal and Fighting-type moves on Ghost-types for neutral damage. Grants immunity to Intimidate and Scare." },
    :STORMDRAIN => { :name => "Storm Drain", :pif => true, :short => "Redirects Water moves. Absorbs them, ups highest Atk.", :full => "The user draws in Water-type moves and gains immunity to them. Additionally, Water-type moves boost the highest attacking stat of the user by one stage." },
    :ICEBODY => { :name => "Ice Body", :pif => true, :short => "Heals 1/8 of max HP every turn in hail.", :full => "Restores 1/8 max HP at the end of each turn in hail. Also grants immunity to hail damage." },
    :SOLIDROCK => { :name => "Solid Rock", :pif => true, :short => "Takes 35% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 35%. Multiplicative with other sources of damage reduction." },
    :SNOWWARNING => { :name => "Snow Warning", :pif => true, :short => "Summons hail on entry. Lasts 8 turns.", :full => "Summons hailstorm for 8 turns (12 with Icy Rock) on entry. Damages non-Ice types by 1/16 HP per turn. Boosts the Defense stat of Ice-type Pokemon by 50%. Halves the effectiveness of sun related moves." },
    :FRISK => { :name => "Frisk", :pif => true, :short => "Checks foes' item and disables their items for two turns.", :full => "Upon entering battle, reveals the opponents' items and prevents them from working for 2 turns. Does not prevent Mega Stones and other similar items from working." },
    :RECKLESS => { :name => "Reckless", :pif => true, :short => "Moves causing recoil damage deal 1.2x more damage.", :full => "Increases the damage of moves that cause recoil by 20%. This bonus also applies when moves gain recoil through other means, such as madness or abilities." },
    :MULTITYPE => { :name => "Multitype", :pif => true, :short => "Held Plate item decides holder's type.", :full => "The user changes form based of the type of Plate they are currently holding. Plates cannot be removed, and Multitype cannot be overridden, suppressed, swapped, or copied in any way." },
    :BADDREAMS => { :name => "Bad Dreams", :pif => true, :short => "Sleeping Pokémon lose 1/4 of max HP at the end of each turn.", :full => "All sleeping opponents lose 25% of their max HP at the end of each turn." },
    :PICKPOCKET => { :name => "Pickpocket", :pif => true, :short => "Steals the foe's held item on contact.", :full => "The user steals the target's held item on contact if they are currently holding no item. Does not work with Mega Stones and other similar items." },
    :SHEERFORCE => { :name => "Sheer Force", :pif => true, :short => "Exchanges added effects on its moves for 1.3x more power.", :full => "Removes most beneficial secondary effects after landing attacks in exchange for a 1.3x boost. Notably prevents Life Orb recoil when using these moves. Removable effects include reducing the target's stats, increasing the user's stats, inflicting status on a target and flinching." },
    :CONTRARY => { :name => "Contrary", :pif => true, :short => "Stat raises turn into stat drops for this Pokémon and vice versa.", :full => "Reverses all stat changes affecting this Pokemon. Works with self-inflicted changes." },
    :UNNERVE => { :name => "Unnerve", :pif => true, :short => "Foes can't use consumable items.", :full => "Prevents all opposing Pokemon from consuming held items." },
    :DEFIANT => { :name => "Defiant", :pif => true, :short => "Raises Attack by two stages if stats are lowered by an enemy.", :full => "When the user has their stats lowered by another Pokemon, they raise their Attack by 2 stages." },
    :DEFEATIST => { :name => "Defeatist", :pif => true, :short => "Halves Atk and Sp. Atk stats if user is below 1/3 of max HP.", :full => "Halves both Attack and Special Attack stats when HP drops below 33% of maximum. Deactivates after healing above this threshold." },
    :CURSEDBODY => { :name => "Cursed Body", :pif => true, :short => "30% chance to disable moves if enemy makes contact.", :full => "The user has a 30% chance to disable the attacker's move for 4 turns when hit by contact moves. The disabled move cannot be selected until the effect wears off." },
    :HEALER => { :name => "Healer", :pif => true, :short => "30% chance to heal user or ally's status at the end of each turn.", :full => "Gives a 30% chance to cure status conditions at the end of each turn for both the user and their ally if they are out in a double battle. Makes 2 separate checks for each Pokemon." },
    :FRIENDGUARD => { :name => "Friend Guard", :pif => true, :short => "Reduces damage that ally takes by 25% in double battles.", :full => "In a double battle, the user's ally receives 25% less damage. Multiplicative with other damage reduction sources." },
    :WEAKARMOR => { :name => "Weak Armor", :pif => true, :short => "If hit by a contact move: -1 Defense and +2 Speed.", :full => "When hit by a contact move, raises the user's Speed by 2 stages and lowers their defense by 1 stage. Activates on each hit of a multihit move." },
    :LIGHTMETAL => { :name => "Light Metal", :pif => true, :short => "Boosts Speed by 1.3x and halves this Pokémon's weight.", :full => "Light Metal halves the Pokemon's weight and boosts their Speed stat by 30%. Makes weight-based attacks such as Low Kick deal less damage against this Pokemon. However, it also decreases damage from the user's Heavy Slam and similar weight-based moves." },
    :MULTISCALE => { :name => "Multiscale", :pif => true, :short => "At full HP, halves damage taken from attacks", :full => "Reduces all incoming damage by 50% when the Pokemon is at max HP. Multiplicative with other sources of damage reduction." },
    :TOXICBOOST => { :name => "Toxic Boost", :pif => true, :short => "Ups Atk by 1.5x if poisoned. Immune to Poison status damage.", :full => "Increases the Pokemon's Attack stat by 50% when poisoned (regular or badly poisoned). Immediately applies poison to user when in Toxic Terrain, regardless of them being grounded or not. Nullifies poison damage." },
    :FLAREBOOST => { :name => "Flare Boost", :pif => true, :short => "Ups Sp. Atk by 1.5x if burned. Ignites in fog.", :full => "Raises the Pokemon's Special Attack stat by 50% when burned. Negates burn damage. Immediately applies burn to self in fog." },
    :HARVEST => { :name => "Harvest", :pif => true, :short => "50% chance to recycle a used Berry every turn, 100% in sun.", :full => "50% chance to restore berry on turn end, 100% in sun. Includes berries that were used for Fling, Natural Gift, or eaten." },
    :TELEPATHY => { :name => "Telepathy", :pif => true, :short => "Protects team from friendly fire.", :full => "Protects the Pokemon from all damage-dealing moves used by its allies in double battles." },
    :MOODY => { :name => "Moody", :pif => true, :short => "Sharply raises one stat and lowers another each turn.", :full => "At the end of each turn, randomly selects one stat to raise by 2 stages and another different stat to lower by 1 stage." },
    :OVERCOAT => { :name => "Overcoat", :pif => true, :short => "Blocks weather dmg and powders. Takes -20% special damage.", :full => "Provides immunity to weather damage from Sandstorm and Hail, and blocks all powder moves including Sleep Powder, Stun Spore, Poison Powder, Spore, Cotton Spore, Rage Powder, Powder, and Magic Powder. Also reduces incoming special damage by 20%. Multiplicative with other damage reduction sources." },
    :POISONTOUCH => { :name => "Poison Touch", :pif => true, :short => "30% chance to poison on contact. Also works on offense.", :full => "Has a 30% chance to inflict poison on contact moves, both when attacking and being attacked." },
    :REGENERATOR => { :name => "Regenerator", :pif => true, :short => "Heals 1/3 of max HP upon switching out.", :full => "Restores 33% of maximum HP when switching out. This heal is not blocked by Heal Block." },
    :BIGPECKS => { :name => "Big Pecks", :pif => true, :short => "Boosts the power of contact moves by 1.3x.", :full => "Boosts the power of contact moves by 30%." },
    :SANDRUSH => { :name => "Sand Rush", :pif => true, :short => "This Pokémon's Speed gets a 1.5x boost in a sandstorm.", :full => "Boosts the Pokemon's Speed stat by 50% in sand. Also grants immunity to sandstorm damage." },
    :WONDERSKIN => { :name => "Wonder Skin", :pif => true, :short => "Blocks most damage boosting and multihit abilities.", :full => "Immune to all damage boosting ability effects from opponents, other than Parental Bond, Familia Bond, and Multi-Headed." },
    :ANALYTIC => { :name => "Analytic", :pif => true, :short => "Attacks get a 1.3x power boost if it moves last.", :full => "When the user moves after the target, boosts attack power by 30%." },
    :ILLUSION => { :name => "Illusion", :pif => true, :short => "Appears as last party slot and boosts power by 1.3x until hit.", :full => "Makes the Pokemon appear as the last alive party member. Boosts the user's damage by 30% until the illusion breaks." },
    :IMPOSTER => { :name => "Imposter", :pif => true, :short => "Transforms into the foe on entry.", :full => "Transforms the Pokemon into the opponent upon switching in. Copies their appearance, stats (minus HP), types, abilities, moves, and stat changes. Each copied move has 5 PP. Cannot transform if the target has Substitute, is already transformed, has Illusion active, or is semi-invulnerable." },
    :INFILTRATOR => { :name => "Infiltrator", :pif => true, :short => "Own moves bypass Substitutes and damage reduction screens.", :full => "Allows moves to bypass the effects of screens, Safeguard, Mist, and Substitute." },
    :MUMMY => { :name => "Mummy", :pif => true, :short => "If hit, makes the attacker's ability Mummy.", :full => "When the user receives a contact move from another Pokemon who does not have this ability, it replaces their current ability with Mummy." },
    :MOXIE => { :name => "Moxie", :pif => true, :short => "Dealing a KO raises Attack by one stage.", :full => "Boosts the user's Attack by one stage whenever it knocks out an opponent with a direct hit." },
    :JUSTIFIED => { :name => "Justified", :pif => true, :short => "Boosts highest attack instead of being hit by Dark-type moves.", :full => "Immune to Dark-type moves, and boost Attack or Special Attack by 1 stage when the user is hit by them, based on whichever stat is higher." },
    :RATTLED => { :name => "Rattled", :pif => true, :short => "If hit by Bug, Dark or Ghost move, or flinches: +1 Speed.", :full => "Boosts Speed by one stage when hit by Bug, Dark, or Ghost-type moves or when the user flinches. Activates multiple times against multihit moves." },
    :MAGICBOUNCE => { :name => "Magic Bounce", :pif => true, :short => "Bounces back the effect of status moves to their user.", :full => "Reflects most status moves back to the user before they can take effect. The bounced move targets the original user with no additional accuracy check. Does not reflect moves that were already reflected." },
    :SAPSIPPER => { :name => "Sap Sipper", :pif => true, :short => "Redirects Grass moves. Absorbs them, ups highest Atk.", :full => "Immune to Grass-type moves, and boost highest attacking stat by 1 stage when the user is hit by them." },
    :PRANKSTER => { :name => "Prankster", :pif => true, :short => "Status moves have +1 priority but fail on opposing Dark-types.", :full => "Status moves gain +1 priority. Status moves fail when directly targeting opposing Dark-type Pokemon." },
    :SANDFORCE => { :name => "Sand Force", :pif => true, :short => "Ups highest attacking stat by 1.5x in sand.", :full => "Boosts the Pokemon's highest attacking stat by 50% in sand. Immune to sandstorm damage." },
    :IRONBARBS => { :name => "Iron Barbs", :pif => true, :short => "Enemies lose 1/8 of max HP if they use a contact move.", :full => "Enemies lose 1/8 of max HP if they use a contact move." },
    :VICTORYSTAR => { :name => "Victory Star", :pif => true, :short => "Gives 1.2x accuracy boost to its own and its allies' moves.", :full => "Boosts the user's and their ally's accuracy by 1.2x when active in a double battle." },
    :TURBOBLAZE => { :name => "Turboblaze", :pif => true, :short => "Moves hit through abilities. Adds Fire type to itself.", :full => "Allows moves to ignore the target's abilities and innates that interfere with effects or reduce damage. Does not bypass abilities that modify base stats such as Grass Pelt. Adds Fire to the user's typing. Retains Fire typing even upon losing the ability, going away only when switching out." },
    :TERAVOLT => { :name => "Teravolt", :pif => true, :short => "Moves hit through abilities. Adds Electric type to itself.", :full => "Allows moves to ignore the target's abilities and innates that interfere with effects or reduce damage. Does not bypass abilities that modify base stats such as Grass Pelt. Adds Electric to the user's typing. Retains Electric typing even upon losing the ability, going away only when switching out." },
    :AROMAVEIL => { :name => "Aroma Veil", :pif => true, :short => "Protects team from infatuation, heal block, and disabling.", :full => "Protects the user and allies from infatuation, heal block effects, and disabling moves including Disable, Taunt, Encore, and Torment." },
    :FLOWERVEIL => { :name => "Flower Veil", :pif => true, :short => "Protects Grass-type allies from status and stat drops.", :full => "Prevents all status conditions and stat reductions for Grass-type allies." },
    :PROTEAN => { :name => "Protean", :pif => true, :short => "Changes type depending on the move it's about to use.", :full => "Before each attack, the user overrides their type to match the move's type. Activates once per turn." },
    :FURCOAT => { :name => "Fur Coat", :pif => true, :short => "Halves damage taken by Physical moves. Does NOT double Defense.", :full => "Halves all incoming Attack damage. Multiplicative with other sources of damage reduction." },
    :MAGICIAN => { :name => "Magician", :pif => true, :short => "Steals the foe's held item after using a non-contact move.", :full => "The user steals the target's held item when landing a non-contact move if they are currently holding no item. Does not work with Mega Stones and other similar items." },
    :BULLETPROOF => { :name => "Bulletproof", :pif => true, :short => "Immune to projectile, ball, or bomb-based moves.", :full => "Provides immunity to ball, bomb, and projectile moves. Includes Acid Spray, Rock Wrecker, Pollen Puff, and Barrage." },
    :COMPETITIVE => { :name => "Competitive", :pif => true, :short => "Raises Sp. Atk by two stages if stats are lowered by an enemy.", :full => "When the user has their stats lowered by another Pokemon, they raise their Special Attack by 2 stages." },
    :STRONGJAW => { :name => "Strong Jaw", :pif => true, :short => "Boosts the power of bite/fang moves by 1.3x.", :full => "Boosts the power of biting and fang moves by 30%." },
    :REFRIGERATE => { :name => "Refrigerate", :pif => true, :short => "Normal moves become Ice. Ice moves are empowered.", :full => "Changes the user's Normal-type moves to Ice-type. If the user is Ice-type its Ice-type moves have a 10% frostbite chance, otherwise it gains Ice STAB." },
    :SWEETVEIL => { :name => "Sweet Veil", :pif => true, :short => "This Pokémon and its ally are immune to sleep.", :full => "Provides sleep immunity to both the user and their ally in double battles." },
    :STANCECHANGE => { :name => "Stance Change", :pif => true, :short => "Turns into Blade or Shield form depending on move used.", :full => "Changes Aegislash's form based on moves used. Shield form switches to Blade when using damaging moves. Blade switches to Shield with King's Shield. Redux forms swap between physical/special based on move type. Unsuppressable. Form changes occur before attacks execute." },
    :GALEWINGS => { :name => "Gale Wings", :pif => true, :short => "Flying-type moves get +1 priority at full HP.", :full => "Grants +1 priority to Flying-type moves when at full HP." },
    :MEGALAUNCHER => { :name => "Mega Launcher", :pif => true, :short => "Boosts Beam/Pump/Cannon/Shot/ Gun/Pulse, etc. moves by 1.3x.", :full => "Boosts pulse, beam, ball, and aura moves by 30%." },
    :GRASSPELT => { :name => "Grass Pelt", :pif => true, :short => "Boosts Defense by 50% in Grassy Terrain.", :full => "Boosts the user's Defense stat by 50% when in Grassy Terrain." },
    :SYMBIOSIS => { :name => "Symbiosis", :pif => true, :short => "Passes own item to its ally if said ally consumes its item.", :full => "Transfers the holder's item to an ally immediately after that ally consumes or uses up their held item." },
    :TOUGHCLAWS => { :name => "Tough Claws", :pif => true, :short => "Boosts the power of contact moves by 1.3x.", :full => "Contact moves are boosted by 30%." },
    :PIXILATE => { :name => "Pixilate", :pif => true, :short => "Normal moves become Fairy. Fairy moves are empowered.", :full => "Changes the user's Normal-type moves to Fairy-type. If the user is Fairy-type its Fairy-type moves have a 10% infatuate chance, otherwise it gains Fairy STAB." },
    :GOOEY => { :name => "Gooey", :pif => true, :short => "Lowers Speed of enemies that make contact with this Pokémon.", :full => "When the user is hit by a contact move, the attacker reduces their Speed by one stage. Activates multiple times against multihit moves." },
    :AERILATE => { :name => "Aerilate", :pif => true, :short => "Normal moves become Flying. Flying moves are empowered.", :full => "Changes the user's Normal-type moves to Flying-type. If the user is Flying-type its Flying-type moves are 10% faster, otherwise it gains Flying STAB." },
    :PARENTALBOND => { :name => "Parental Bond", :pif => true, :short => "Moves hit twice. 1st hit at 100% power, 2nd hit at 25%.", :full => "Makes all attacks hit twice in succession. The first hit deals 100%, while the second hit deals 25%. Each hit rolls secondary effects independently (except flinch). Bypasses Fort Knox/Wonder Skin." },
    :DARKAURA => { :name => "Dark Aura", :pif => true, :short => "Boosts Dark moves by 1.33x for all while this Pokémon is out.", :full => "All Dark-type moves for the user, their allies, and the opponent get a 1.33x boost. Boost is reversed by Aura Break." },
    :FAIRYAURA => { :name => "Fairy Aura", :pif => true, :short => "Boosts Fairy moves by 1.33x for all while this Pokémon is out.", :full => "All Fairy-type moves for the user, their allies, and the opponent get a 1.33x boost. Boost is reversed by Aura Break." },
    :STAMINA => { :name => "Stamina", :pif => true, :short => "Boosts Defense by +1 when hit. Critical hits maximize Defense.", :full => "When hit, raises the user's Defense by 1 stage or maximizes it on critical hits. Activates on each hit of a multihit move." },
    :WIMPOUT => { :name => "Wimp Out", :pif => true, :short => "At 1/2 of max HP or below, instantly switches out.", :full => "When the Pokemon receives damage and its HP drops to 50% or below for the first time in battle, it switches out to safety. Activates on the last hit of multihit moves." },
    :EMERGENCYEXIT => { :name => "Emergency Exit", :pif => true, :short => "At 1/2 of max HP or below, instantly switches out.", :full => "When the Pokemon receives damage and its HP drops to 50% or below for the first time in battle, it switches out to safety. Activates on the last hit of multihit moves." },
    :WATERCOMPACTION => { :name => "Water Compaction", :pif => true, :short => "Takes 1/2 dmg from Water-type moves. +2 Def when hit by those.", :full => "Reduces damage from Water-type moves by 50% and raises Defense by 2 stages when hit by Water moves. Multiplicative with other sources of damage reduction. Defense boost applies after the hit lands. Activates on each hit of a multihit move." },
    :MERCILESS => { :name => "Merciless", :pif => true, :short => "Always crits slowed, poisoned, paralyzed, or bleeding foes.", :full => "Guarantees critical hits against targets who are poisoned, paralyzed, bleeding, or have their speed lowered." },
    :SHIELDSDOWN => { :name => "Shields Down", :pif => true, :short => "At 1/2 of max HP or below, transforms into Core form.", :full => "Transforms Minior from Meteor Form to Core Form when HP drops to 50% or below. In Meteor Form, grants immunity to all status conditions. When using Shell Smash, immediately transforms to Core Form regardless of current HP. Cannot revert to Meteor Form once transformed during battle." },
    :STAKEOUT => { :name => "Stakeout", :pif => true, :short => "Deals double damage to opponents being switched in.", :full => "Deals double damage to opponents that just switched in. Only works right after they switch in for 1 turn." },
    :WATERBUBBLE => { :name => "Water Bubble", :pif => true, :short => "Halves Fire dmg taken. Doubles Water dmg dealt. No burns.", :full => "Doubles the power of Water-type moves and reduces Fire-type damage taken by 50%. Also provides complete immunity to burns, removing existing burns upon gaining the ability." },
    :STEELWORKER => { :name => "Steelworker", :pif => true, :short => "Normal moves become Steel. Steel resists Ghost and Dark.", :full => "Changes the user's Normal-type moves to Steel-type. If the user is Steel-type it resists Ghost and Dark, otherwise it gains Steel STAB." },
    :BERSERK => { :name => "Berserk", :pif => true, :short => "Boosts highest attack by +1 when at 1/2 of max HP or lower.", :full => "Berserk activates when the Pokemon drops to half HP or below from an opposing attack, boosting its highest attacking stat by one stage. Includes stat stages to determine which gets boosted. Triggers only once per battle. Other damage sources that bring you to half HP or below will not activate it." },
    :SLUSHRUSH => { :name => "Slush Rush", :pif => true, :short => "This Pokémon's Speed gets a 1.5x boost in hail.", :full => "Boosts the Pokemon's Speed stat by 50% during hail. Also grants immunity to hail damage." },
    :LONGREACH => { :name => "Long Reach", :pif => true, :short => "Physical moves get a 1.2x bonus and don't make contact.", :full => "Long Reach prevents the user from making contact with targets when using contact moves. Additionally, physical moves receive a 1.2x damage boost." },
    :LIQUIDVOICE => { :name => "Liquid Voice", :pif => true, :short => "Sound moves get a 1.2x boost and become Water if Normal.", :full => "Liquid Voice converts Normal-type sound moves to Water-type and boosts them by 20%." },
    :TRIAGE => { :name => "Triage", :pif => true, :short => "Moves that restore HP gain +3 priority.", :full => "Triage grants +3 priority to most HP healing moves. Includes draining moves like Giga Drain, and delayed healing moves like Wish. Does not work with Aqua Ring, Grassy Terrain, Ingrain, Leech Seed, Pain Split, Present, or Pollen Puff." },
    :GALVANIZE => { :name => "Galvanize", :pif => true, :short => "Normal moves become Electric. Electric moves are empowered.", :full => "Changes the user's Normal-type moves to Electric-type. If the user is Electric-type its Electric-type moves have a 10% chance to paralyze, otherwise it gains Electric STAB." },
    :DISGUISE => { :name => "Disguise", :pif => true, :short => "Protects once against an attack. Restores protection in fog.", :full => "Disguise blocks the first damaging move that hits the Pokemon and changes its form after. Only non-status moves are blocked. In fog, the disguise is restored immediately once per switch in, or when fog is set again." },
    :CORROSION => { :name => "Corrosion", :pif => true, :short => "Poison is super effective vs Steel. Can poison any type.", :full => "Poison-type moves become super effective against Steel-type Pokemon. Additionally, this Pokemon can inflict poison status on any type." },
    :COMATOSE => { :name => "Comatose", :pif => true, :short => "Can move, but is always asleep. Immune to status conditions.", :full => "Comatose considers the user as asleep for moves and statuses. The Pokemon can move normally and gains immunity to all status conditions. Cannot be copied or suppressed. Rest fails when used." },
    :QUEENLYMAJESTY => { :name => "Queenly Majesty", :pif => true, :short => "Protects itself and ally from priority moves.", :full => "Queenly Majesty prevents the user and its ally from being targeted by priority moves with priority higher than 0." },
    :INNARDSOUT => { :name => "Innards Out", :pif => true, :short => "If KO'd, deals as much damage as what the fatal attack dealt.", :full => "Innards Out activates when the Pokemon is knocked out by an opponent's attack. It inflicts the same amount of damage the fatal attack dealt back to the attacker. Cannot affect attackers protected by Magic Guard." },
    :DANCER => { :name => "Dancer", :pif => true, :short => "Copies dance moves used by others.", :full => "When any Pokemon on the field uses a dance move, this Pokemon immediately uses the same move after. Triggers once per move." },
    :FLUFFY => { :name => "Fluffy", :pif => true, :short => "Halves contact damage taken. 2x weak to Fire-type moves.", :full => "Fluffy reduces damage from contact moves by 50%. Fire-type moves to deal double damage to the user. Multiplicative with other forms of damage reduction." },
    :DAZZLING => { :name => "Dazzling", :pif => true, :short => "Protects itself and ally from priority moves.", :full => "Dazzling blocks all priority moves from opponents targeting the user or allies." },
    :SOULHEART => { :name => "Soul-Heart", :pif => true, :short => "KOs dealt anywhere on the field raise Sp. Atk by one stage.", :full => "Soul-Heart raises Special Attack by one stage when any Pokemon faints on the battlefield, including allies and enemies." },
    :TANGLINGHAIR => { :name => "Tangling Hair", :pif => true, :short => "Lowers Speed of enemies that make contact with this Pokémon.", :full => "When the user is hit by a contact move, the attacker reduces their Speed by one stage. Activates multiple times against multihit moves." },
    :RECEIVER => { :name => "Receiver", :pif => true, :short => "In Double Battles, copies its fainting partner's ability.", :full => "Receiver copies a fainted ally's ability, replacing Receiver. Persists until switched out." },
    :BEASTBOOST => { :name => "Beast Boost", :pif => true, :short => "Dealing a KO raises highest calculated stat by one stage.", :full => "Beast Boost raises the user's highest calculated stat by one stage each time it KOs an opponent. The stat raised is determined by comparing the raw stat without current modifiers such as stat raises." },
    :ELECTROSURGE => { :name => "Electro Surge", :pif => false, :short => "Casts Electric Terrain on entry. Lasts 8 turns.", :full => "Creates Electric Terrain for 8 turns (12 with Terrain Extender) upon entry. Grounded Pokemon cannot fall asleep and Electric moves gain 30% power boost. Overrides other terrains when activated." },
    :PSYCHICSURGE => { :name => "Psychic Surge", :pif => true, :short => "Casts Psychic Terrain on entry. Lasts 8 turns.", :full => "Creates Psychic Terrain for 8 turns (12 with Terrain Extender) on entry. Grounded Pokemon are immune to priority moves from opponents. Psychic moves gain 30% power boost. Expanding Force hits all foes with increased power. Nature Power becomes Psychic. Overrides other existing terrains." },
    :MISTYSURGE => { :name => "Misty Surge", :pif => true, :short => "Casts Misty Terrain on entry. Lasts 8 turns.", :full => "Creates Misty Terrain on entry, lasting 8 turns (12 with Terrain Extender). Misty Terrain prevents all status conditions for grounded Pokemon and boosts Fairy-type moves by 30%. Overrides existing terrain." },
    :GRASSYSURGE => { :name => "Grassy Surge", :pif => true, :short => "Casts Grassy Terrain on entry. Lasts 8 turns.", :full => "Creates Grassy Terrain for 8 turns (12 with Terrain Extender) on entry. Grounded Pokemon heal 1/16 HP per turn and Grass moves gain 30% power. Overrides other terrains." },
    :FULLMETALBODY => { :name => "Full Metal Body", :pif => true, :short => "Immune to stat drops.", :full => "Full Metal Body gives immunity to all stat reductions from moves and abilities. Includes self stat drops from moves like Overheat." },
    :SHADOWSHIELD => { :name => "Shadow Shield", :pif => true, :short => "At full HP, halves damage taken from attacks", :full => "Shadow Shield halves damage from all attacks when at full HP. Multiplicative with other damage reduction sources." },
    :PRISMARMOR => { :name => "Prism Armor", :pif => true, :short => "Takes 35% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 35%. Multiplicative with other sources of damage reduction." },
    :NEUROFORCE => { :name => "Neuroforce", :pif => true, :short => "Grants an additional 1.35x boost to Super-effective moves.", :full => "Super effective attacks are boosted by 35%." },
    :DAUNTLESSSHIELD => { :name => "Dauntless Shield", :pif => false, :short => "On entry, raises Defense by one stage.", :full => "Dauntless Shield immediately raises Defense by one stage when entering battle." },
    :COTTONDOWN => { :name => "Cotton Down", :pif => false, :short => "Lowers the Speed of all foes by one stage when hit.", :full => "Cotton Down triggers when the Pokemon is hit by any attack, lowering the Speed of ALL Pokemon by one stage. Activates multiple times against multihit moves." },
    :PROPELLERTAIL => { :name => "Propeller Tail", :pif => false, :short => "Swift Swim + Redirection Immunity.", :full => "Propeller Tail boosts the user's Speed by 50% during rain and grants immunity to redirection effects. The speed boost works in all forms of rain." },
    :MIRRORARMOR => { :name => "Mirror Armor", :pif => false, :short => "Bounces back any stat drops inflicted by an enemy.", :full => "Mirror Armor reflects all stat-lowering effects aimed at the user back to the attacker. The reflection bypasses immunities." },
    :STALWART => { :name => "Stalwart", :pif => false, :short => "Isn't affected by redirection, crits, or ability suppression.", :full => "Can't have its moves redirected, can't be critically hit, and can't have its abilities suppressed. Ability suppression includes effects such as Mold Breaker, Gastro Acid, Neutralizing Gas, and Mycelium Might." },
    :PUNKROCK => { :name => "Punk Rock", :pif => false, :short => "Sound moves deal 1.3x more dmg. Takes -50% dmg from sound moves.", :full => "Punk Rock amplifies the user's sound moves by 30% and reduces incoming sound move damage by 50%. Damage reduction is multiplicative with other sources." },
    :ICESCALES => { :name => "Ice Scales", :pif => false, :short => "Halves damage taken by Special moves. Does NOT double SpDef.", :full => "Halves all incoming Special Attack damage. Multiplicative with other sources of damage reduction." },
    :POWERSPOT => { :name => "Power Spot", :pif => false, :short => "Grants a 1.3x boost to ally's attacks.", :full => "Power Spot boosts allies' attack power by 30% in double battles. The user itself receives no boost." },
    :MIMICRY => { :name => "Mimicry", :pif => false, :short => "Changes type depending on active Terrain.", :full => "Mimicry changes the Pokemon's type to match active terrain: Electric on Electric Terrain, Fairy on Misty Terrain, Grass on Grassy Terrain, or Psychic on Psychic Terrain. The type change persists until terrain ends or the Pokemon switches out. Retains type changes from moves like Soak." },
    :SCREENCLEANER => { :name => "Screen Cleaner", :pif => false, :short => "Clears screens from both sides on entry. Can reset screens.", :full => "Screen Cleaner removes all protective screens from both sides of the battlefield -Reflect, Light Screen, Aurora Veil, and Smokescreen - when the Pokemon enters battle. It also allows the Pokemon to set screens while they are already active, refreshing their duration." },
    :STEELYSPIRIT => { :name => "Steely Spirit", :pif => false, :short => "Boosts own & ally's Steel-type moves by 1.3x.", :full => "Steely Spirit increases the power of Steel-type moves by 30% for both the user and its allies in battle." },
    :PERISHBODY => { :name => "Perish Body", :pif => false, :short => "Uses Perish Song when hit by a contact move.", :full => "When hit by a contact move, Perish Body activates Perish Song on both the user and the attacker. Both Pokemon will faint in 3 turns unless they switch out." },
    :GORILLATACTICS => { :name => "Gorilla Tactics", :pif => false, :short => "Raises own Atk by 1.5x, but can only use the first chosen move.", :full => "Gorilla Tactics boosts physical move power by 50% but locks the user into using the first move selected until they switch out." },
    :NEUTRALIZINGGAS => { :name => "Neutralizing Gas", :pif => false, :short => "All abilities are nullified.", :full => "Fills the area with gas that completely suppresses all abilities except unsuppressable ones. Effect lasts while user is on field. After the user attempts to switch, all suppressed abilities reactivate their entry effects. Cannot be copied or swapped." },
    :PASTELVEIL => { :name => "Pastel Veil", :pif => false, :short => "Casts Safeguard on entry. Immune to poison.", :full => "Pastel Veil automatically sets up Safeguard for the user's team when the Pokemon enters battle. Safeguard lasts for 5 turns and protects all team members from status conditions. It also cures its allies' poison on entry, and it and its allies can't be poisoned." },
    :QUICKDRAW => { :name => "Quick Draw", :pif => false, :short => "30% chance to move first.", :full => "Quick Draw gives a 30% chance for the user to act first in their priority bracket. Stacks multiplicatively with Quick Claw for a 44% chance to activate." },
    :TRANSISTOR => { :name => "Transistor", :pif => false, :short => "Boosts the power of Electric-type moves by 1.5x.", :full => "Transistor increases the power of all Electric-type moves by 50%. Stacks additively with other damage modifiers." },
    :DRAGONSMAW => { :name => "Dragon's Maw", :pif => false, :short => "Boosts the power of Dragon-type moves by 1.5x.", :full => "Dragon's Maw boosts the power of Dragon-type moves by 50%." },
    :CHLOROPLAST => { :name => "Chloroplast", :pif => false, :short => "Weather Ball, Solar Beam/Blade, Growth act as if used in sun.", :full => "Weather Ball doubles power and becomes Fire-type. Solar moves charge instantly. Growth boosts Attack and Special Attack by 2 stages. Moonlight, Morning Sun, and Synthesis recover 2/3 of your max HP. Grass and Water Pledge creates a sea of fire or rainbow respectively." },
    :WHITEOUT => { :name => "Whiteout", :pif => false, :short => "Ups highest attacking stat by 1.5x in hail.", :full => "Whiteout boosts the Pokemon's highest attacking stat by 50% during hail. Also grants immunity to hail damage." },
    :PYROMANCY => { :name => "Pyromancy", :pif => false, :short => "Moves inflict burn 5x as often.", :full => "Pyromancy multiplies the burn chance of all moves by 5x. Does not interact with Flame Body." },
    :KEENEDGE => { :name => "Keen Edge", :pif => false, :short => "Boosts the power of slashing moves by 1.3x.", :full => "Keen Edge boosts all slashing attacks by 30%." },
    :PRISMSCALES => { :name => "Prism Scales", :pif => false, :short => "Takes 30% less damage from Special attacks.", :full => "Prism Scales reduces damage from all Special attacks by 30%. Stacks multiplicatively with other damage reduction sources." },
    :POWERFISTS => { :name => "Power Fists", :pif => false, :short => "Iron Fist moves target Special Defense and get a 1.3x boost.", :full => "Punching moves gain a 30% damage boost and target Special Defense instead of Defense." },
    :SANDSONG => { :name => "Sand Song", :pif => false, :short => "Sound moves get a 1.2x boost and become Ground if Normal.", :full => "Sand Song boosts the power of all sound-based moves by 20% and converts Normal-type sound moves to Ground-type." },
    :RAMPAGE => { :name => "Rampage", :pif => false, :short => "No recharge after a KO, if it usually would need to recharge.", :full => "Rampage eliminates recharge turns when the user successfully KOs an opponent with a direct attack." },
    :VENGEANCE => { :name => "Vengeance", :pif => false, :short => "Boosts Ghost-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Ghost-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :BLITZBOXER => { :name => "Blitz Boxer", :pif => false, :short => "Punching moves get +1 priority at full HP.", :full => "Blitz Boxer grants +1 priority to all punching moves when at full HP." },
    :ANTARCTICBIRD => { :name => "Antarctic Bird", :pif => false, :short => "Ice-type and Flying-type moves get a 1.3x power boost.", :full => "Antarctic Bird grants a 1.3x power boost to both Ice-type and Flying-type moves. Additive with other damage boosts." },
    :IMMOLATE => { :name => "Immolate", :pif => false, :short => "Normal moves become Fire. Fire moves are empowered.", :full => "Changes the user's Normal-type moves to Fire-type. If the user is Fire-type its Fire-type moves have a 10% chance to burn, otherwise it gains Fire STAB." },
    :ELECTROCYTES => { :name => "Electrocytes", :pif => false, :short => "Boosts the power of Electric-type moves by 1.25x.", :full => "Electrocytes boosts Electric-type moves by 25%." },
    :AERODYNAMICS => { :name => "Aerodynamics", :pif => false, :short => "Boosts Speed instead of being hit by Flying-type moves.", :full => "When targeted by Flying-type moves, Aerodynamics absorbs the attack and raises the user's Speed stat by one stage." },
    :EXPLOITWEAKNESS => { :name => "Exploit Weakness", :pif => false, :short => "Targets lowest defense vs statused foes.", :full => "When attacking a statused opponent, targets their lower defensive stat." },
    :GROUNDSHOCK => { :name => "Ground Shock", :pif => false, :short => "Target Grounds aren't immune to Electric but resist it instead.", :full => "Ground Shock allows Electric moves to hit Ground-type Pokemon for 0.5x damage." },
    :ANCIENTIDOL => { :name => "Ancient Idol", :pif => false, :short => "Uses Def and Sp. Def instead of Atk and Sp. Atk when attacking.", :full => "Physical moves use the Defense stat of the user instead of Attack for damage, while special moves use the Special Defense stat of the user instead of Special Attack." },
    :MYSTICPOWER => { :name => "Mystic Power", :pif => false, :short => "All moves gain the 1.5x power boost from STAB.", :full => "Mystic Power grants the 1.5x STAB damage bonus to all moves regardless of type matching. Does not boost moves that already receive a STAB bonus." },
    :PERFECTIONIST => { :name => "Perfectionist", :pif => false, :short => "Move BP < 51 BP: +1 to crit rate. Move BP < 26 BP: +1 priority too.", :full => "Attacks with 50 BP or less raise their critical hit ratio by one stage, and attacks with 25 BP or lower also gain +1 priority." },
    :GROWINGTOOTH => { :name => "Growing Tooth", :pif => false, :short => "Raises Attack by +1 when the user's biting moves hit.", :full => "Growing Tooth boosts the user's Attack by one stage whenever they successfully hit with a biting move." },
    :INFLATABLE => { :name => "Inflatable", :pif => false, :short => "Ups Def and Sp. Def by one stage if hit by Flying or Fire moves.", :full => "When hit by any Fire or Flying moves, boost Defense and Special Defense by one stage each. Activates on each hit of a multihit move. The boost applies after the hit lands." },
    :AURORABOREALIS => { :name => "Aurora Borealis", :pif => false, :short => "Ice-type moves gain STAB. Moves always benefit from hail.", :full => "Aurora Borealis grants STAB to all Ice-type moves regardless of the Pokemon's typing. Weather Ball becomes Ice-type with doubled power, Aurora Veil works without hail, and weather-based Ice moves like Blizzard to never miss." },
    :AVENGER => { :name => "Avenger", :pif => false, :short => "If a party Pokémon fainted last turn, next move gets 1.5x boost.", :full => "Avenger boosts the power of all moves by 50% for one turn after any party Pokemon faints." },
    :LETSROLL => { :name => "Let's Roll", :pif => false, :short => "Casts Defense Curl on entry.", :full => "Let's Roll automatically raises Defense by one stage and applies the Defense Curl status upon entering battle, doubling the power of Rollout and other rolling moves." },
    :AQUATIC => { :name => "Aquatic", :pif => false, :short => "Adds Water type on entry.", :full => "Upon entering battle, adds Water to the user's current typing. Retains Water typing even upon losing the ability, going away only when switching out." },
    :LOUDBANG => { :name => "Loud Bang", :pif => false, :short => "Sound-based moves have 50% chance to confuse the foe.", :full => "Sound-based attacks have a 50% chance to confuse the target upon a successful hit." },
    :LEADCOAT => { :name => "Lead Coat", :pif => false, :short => "Take 40% less phys. dmg, but Speed x0.9. Triple user's weight.", :full => "Lead Coat reduces physical damage by 40% but decreases Speed by 10%. Also triples the user's weight. The damage reduction is multiplicative with other sources." },
    :AMPHIBIOUS => { :name => "Amphibious", :pif => false, :short => "Water moves gain STAB. Can't become drenched.", :full => "Grants STAB to Water-type moves regardless of the user's typing. Also provides immunity to being drenched." },
    :GROUNDED => { :name => "Grounded", :pif => false, :short => "Adds Ground type on entry.", :full => "Grounded adds Ground type to the Pokemon upon entry. Retains Ground typing even upon losing the ability, going away only when switching out." },
    :EARTHBOUND => { :name => "Earthbound", :pif => false, :short => "Boosts Ground-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Ground-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :FIGHTINGSPIRIT => { :name => "Fighting Spirit", :pif => false, :short => "Normal moves become Fighting. Fighting moves are empowered.", :full => "Changes the user's Normal-type moves to Fighting-type. If the user is Fighting-type its Fighting-type moves break screens, otherwise it gains Fighting STAB." },
    :COILUP => { :name => "Coil Up", :pif => false, :short => "First biting move each entry gets +1 priority.", :full => "On entry, gives +1 priority to the first biting move used. Priority boost is consumed after landing any biting move." },
    :FOSSILIZED => { :name => "Fossilized", :pif => false, :short => "Halves dmg taken by Rock moves. Boosts own Rock moves by 1.2x.", :full => "Fossilized reduces Rock-type damage by 50% and boosts the user's Rock moves by 20%. Damage reduction is multiplicative with other sources, while the damage boost is additive with other sources." },
    :MAGICALDUST => { :name => "Magical Dust", :pif => false, :short => "Makes foe Psychic-type on contact. Also works on offense.", :full => "If the user makes contact with another Pokemon, offensively or defensively, the other Pokemon's type is changed to pure Psychic. This happens immediately for multihit or priority moves and can remove STAB in the middle of an enemy's multihit move." },
    :DREAMCATCHER => { :name => "Dreamcatcher", :pif => false, :short => "Doubles damage if an opponent is sleeping. Pursues sleeping foes.", :full => "Dreamcatcher doubles the power of the user's moves when any opponent on the field is asleep. This includes the user, allies, or opponents. Attacks hit sleeping foes who are switching out for 1x power instead, damaging them before leaving. Does not activate against Comatose." },
    :NOCTURNAL => { :name => "Nocturnal", :pif => false, :short => "Boosts own Dark moves by 1.25x. Takes -25% dmg from Dark/Fairy.", :full => "Dark-type moves receive a 25% boost, and the user takes 25% less damage from Dark and Fairy moves. The damage reduction is multiplicative with other sources." },
    :SELFSUFFICIENT => { :name => "Self Sufficient", :pif => false, :short => "Recovers 1/16 of max HP at the end of each turn.", :full => "Recovers 1/16 of max HP at the end of each turn." },
    :TECTONIZE => { :name => "Tectonize", :pif => false, :short => "Normal moves become Ground. Ground ignores certain hazards.", :full => "Changes the user's Normal-type moves to Ground-type. If the user is Ground-type it is immune to Stealth Rocks and Spikes, otherwise it gains Ground STAB." },
    :HALFDRAKE => { :name => "Half Drake", :pif => false, :short => "Adds Dragon type on entry.", :full => "Upon entering battle, adds Dragon to the user's current typing. Retains Dragon typing even upon losing the ability, going away only when switching out." },
    :LIQUIFIED => { :name => "Liquified", :pif => false, :short => "Takes 1/2 dmg from contact moves but Water moves hurt it 2x more.", :full => "Liquified reduces contact move damage by 50% but doubles Water-type move damage taken. Multiplicative with other damage reduction sources." },
    :DRAGONFLY => { :name => "Dragonfly", :pif => false, :short => "Adds Dragon type on entry. Avoids Ground attacks.", :full => "Upon entering battle, adds Dragon to the user's current typing. Retains Dragon typing even upon losing the ability, going away only when switching out. Also gives the user immunity to Ground-type attacks and field effects that require you to be grounded." },
    :DRAGONSLAYER => { :name => "Dragonslayer", :pif => false, :short => "Deal 1.5x dmg to Dragon-types. Take 0.5x dmg from Dragon-types.", :full => "Deals 1.5x damage to Dragon-type Pokemon and takes 0.5x damage when attacked by Dragon-type Pokemon. Based on attacker/defender Pokemon types, not move types. The damage reduction is multiplicative with other sources." },
    :MOUNTAINEER => { :name => "Mountaineer", :pif => false, :short => "Immune to Rock-type attacks and Stealth Rock damage.", :full => "Mountaineer grants immunity to all Rock-type moves and Stealth Rock entry hazard damage." },
    :HYDRATE => { :name => "Hydrate", :pif => false, :short => "Normal moves become Water. Water moves are empowered.", :full => "Changes the user's Normal-type moves to Water-type. If the user is Water-type its Water-type moves have a 10% chance to drench, otherwise it gains Water STAB." },
    :METALLIC => { :name => "Metallic", :pif => false, :short => "Adds Steel type on entry.", :full => "Upon entering battle, adds Steel to the user's current typing. Retains Steel typing even upon losing the ability, going away only when switching out." },
    :PERMAFROST => { :name => "Permafrost", :pif => false, :short => "Takes 35% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 35%. Multiplicative with other sources of damage reduction." },
    :PRIMALARMOR => { :name => "Primal Armor", :pif => false, :short => "Takes 50% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 50%. Multiplicative with other sources of damage reduction." },
    :RAGINGBOXER => { :name => "Raging Boxer", :pif => false, :short => "Punching moves hit twice. 1st hit at 100% power, 2nd hit at 40%.", :full => "Raging Boxer causes punching moves to hit twice, with the first hit at 100% power and second hit at 40% power. Both attacks independently roll secondary effect chances (except flinch)." },
    :AIRBLOWER => { :name => "Air Blower", :pif => false, :short => "Casts a 3-turn Tailwind on entry.", :full => "Air Blower automatically sets up a 3-turn Tailwind upon entering battle, doubling the Speed of all Pokemon on the user's side. Also activates Wind Rider." },
    :JUGGERNAUT => { :name => "Juggernaut", :pif => false, :short => "Contact moves add 20% Def to attack. Paralysis-immune.", :full => "Juggernaut boosts contact moves by adding 20% of the user's Defense stat to attack calculations. Prevents paralysis and immediately cures the status if inflicted on the user." },
    :SHORTCIRCUIT => { :name => "Short Circuit", :pif => false, :short => "Boosts Electric-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Electric-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :MAJESTICBIRD => { :name => "Majestic Bird", :pif => false, :short => "Boosts own Sp. Atk by 1.5x. Boosts raw stat, not base stat.", :full => "Majestic Bird boosts the user's Special Attack stat by 50%. Multiplicative with other damage boosts." },
    :PHANTOM => { :name => "Phantom", :pif => false, :short => "Adds Ghost type on entry.", :full => "Upon entering battle, adds Ghost to user's current typing. Retains Ghost typing even upon losing the ability, going away only when switching out." },
    :INTOXICATE => { :name => "Intoxicate", :pif => false, :short => "Normal moves become Poison. Poison moves are empowered.", :full => "Changes the user's Normal-type moves to Poison-type. If the user is Poison-type its Poison-type moves have a 10% chance to badly poison, otherwise it gains Poison STAB." },
    :IMPENETRABLE => { :name => "Impenetrable", :pif => false, :short => "Only damaged by attacks.", :full => "Impenetrable grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil." },
    :HYPNOTIST => { :name => "Hypnotist", :pif => false, :short => "Hypnosis accuracy is 90% when used by this Pokémon.", :full => "Boosts Hypnosis' accuracy to 90%. Does not lock to accuracy to 90%, the move still gets affected by accuracy/evasiveness changes." },
    :OVERWHELM => { :name => "Overwhelm", :pif => false, :short => "Hits Fairies with Dragon moves. Immune to Intimidate and Scare.", :full => "Allows Dragon-type moves to hit Fairy-type Pokemon for normal damage instead of having no effect. Additionally, the user is immune to Intimidate and Scare." },
    :SCARE => { :name => "Scare", :pif => false, :short => "Lowers foes' Sp. Atk by one stage on entry.", :full => "Upon entering battle, the user drops the Special Attack stat of all opposing Pokemon by one stage." },
    :MAJESTICMOTH => { :name => "Majestic Moth", :pif => false, :short => "On entry, raises highest calculated stat by one stage.", :full => "Majestic Moth raises the user's highest calculated base stat by 1 stage when it enters battle." },
    :SOULEATER => { :name => "Soul Eater", :pif => false, :short => "Dealing a KO heals 1/4 of this Pokémon's max HP.", :full => "When the user knocks out an opponent with a direct hit, it immediately recovers 25% of its maximum HP." },
    :SOULLINKER => { :name => "Soul Linker", :pif => false, :short => "Enemies take all the damage they deal, same for this Pokémon.", :full => "When the user takes a direct hit, the opponent takes identical damage. When landing a direct hit, the user also takes the same damage it inflicts. Does not activate when either Pokemon is knocked out, taking damage from Pain Split, or against another Soul Linker." },
    :SWEETDREAMS => { :name => "Sweet Dreams", :pif => false, :short => "Heals 1/8 of max HP every turn if asleep. Immune to Bad Dreams.", :full => "Sweet Dreams restores 1/8 of maximum HP at the end of each turn when the user is asleep or has the Comatose ability. Additionally, it grants immunity to Bad Dreams damage." },
    :BADLUCK => { :name => "Bad Luck", :pif => false, :short => "Foes can't crit, deal min damage, 5% less acc, & no effect chance.", :full => "Foes can not land critical hits, always roll minimum damage (85% instead of 85-100%), fail to inflict secondary effects that are not guaranteed, and have a 5% chance to miss a move." },
    :HAUNTEDSPIRIT => { :name => "Haunted Spirit", :pif => false, :short => "When this Pokémon is KO'd, casts a Curse on the attacker.", :full => "Curses the attacker when knocked out by a direct hit. The curse inflicts 25% max HP damage per turn until the cursed Pokemon switches out or faints. Ghost-type attackers are immune to the curse." },
    :ELECTRICBURST => { :name => "Electric Burst", :pif => false, :short => "Electric-type moves deal 1.35x damage but have 10% recoil.", :full => "Electric Burst boosts Electric-type moves by 35% but causes 10% recoil damage based on damage dealt (minimum 1 HP). The recoil damage will not knock out the user." },
    :RAWWOOD => { :name => "Raw Wood", :pif => false, :short => "Halves dmg taken by Grass moves. Boosts own Grass moves by 1.2x.", :full => "Reduces damage from Grass-type attacks by 50% while boosting the power of the user's own Grass-type moves by 20%. Damage reduction is multiplicative with other sources." },
    :SOLENOGLYPHS => { :name => "Solenoglyphs", :pif => false, :short => "Biting moves have a 50% chance to badly poison the target.", :full => "Solenoglyphs gives all biting moves a 50% chance to badly poison the target when landing." },
    :SPIDERLAIR => { :name => "Spider Lair", :pif => false, :short => "Casts Sticky Web on entry. Lasts 5 turns.", :full => "Sets Sticky Web on opponent's field when the user enters battle. Lasts 5 turns and lowers Speed by 1 stage for any grounded Pokemon switching in. Cannot activate if Sticky Web is already present on opponent's field." },
    :FATALPRECISION => { :name => "Fatal Precision", :pif => false, :short => "Super-effective moves never miss and always crit.", :full => "Super-effective damaging moves never miss and always land critical hits." },
    :FORTKNOX => { :name => "Fort Knox", :pif => false, :short => "Blocks most damage boosting and multihit abilities.", :full => "Immune to all damage boosting ability effects from opponents, other than Parental Bond, Familia Bond, and Multi-Headed." },
    :SEAWEED => { :name => "Seaweed", :pif => false, :short => "Takes 1/2 dmg from Fire if Grass. Grass deals x2 dmg to Fire.", :full => "If user is Grass-type, they take half damage from Fire-type attacks and deals 2x damage to Fire-type Pokemon with Grass-type moves. Multiplicative with other sources of damage reduction." },
    :PSYCHICMIND => { :name => "Psychic Mind", :pif => false, :short => "Boosts Psychic-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Psychic-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :POISONABSORB => { :name => "Poison Absorb", :pif => false, :short => "Redirects and absorbs Poison moves. Heals in Toxic Terrain.", :full => "The user draws in Poison-type moves and gains immunity to them, healing for 1/4th of max HP instead. Additionally, heals 1/8th of max HP per turn on Toxic Terrain." },
    :SCAVENGER => { :name => "Scavenger", :pif => false, :short => "Dealing a KO heals 1/4 of this Pokémon's max HP.", :full => "When this Pokemon defeats an opponent with a direct hit, it immediately regains 25% of its maximum HP." },
    :TWISTDIMENSION => { :name => "Twist. Dimension", :pif => false, :short => "Sets up Trick Room on entry, lasts 3 turns.", :full => "Sets up Trick Room on entry, lasts 3 turns." },
    :MULTIHEADED => { :name => "Multi-Headed", :pif => false, :short => "Hits as many times, as it has heads.", :full => "Attack 2-3 times per move based on number of heads. Two-headed Pokemon strike twice (1st hit does 100%, 2nd does 25%), three-headed hit thrice (1st hit does 100%, 2nd does 20%, 3rd does 15%). Each hit rolls secondary effects independently (except flinch). Bypasses Fort Knox/Wonder Skin." },
    :NORTHWIND => { :name => "North Wind", :pif => false, :short => "3 turns Aurora Veil on entry. Immune to Hail damage.", :full => "Sets up Aurora Veil upon entering battle, cutting physical and special damage recieved by half for your entire team. Aurora Veil lasts 3 turns, or 5 turns with Light Clay. The user is also immune to Hail damage. Cannot trigger again if Aurora Veil is already active." },
    :OVERCHARGE => { :name => "Overcharge", :pif => false, :short => "Electric is super effective vs Electric. Can paralyze Electric.", :full => "The user's Electric-type moves become effective against Electric-type Pokemon, dealing 2x damage instead of 0.5x. Also allows the user to paralyze Electric-types." },
    :VIOLENTRUSH => { :name => "Violent Rush", :pif => false, :short => "Boosts Speed by 50% + Attack by 20% on first turn.", :full => "The user gains a 50% Speed boost and 20% Attack boost on their first turn after switching in." },
    :FLAMINGSOUL => { :name => "Flaming Soul", :pif => false, :short => "Fire-type moves get +1 priority at full HP.", :full => "Grants +1 priority to Fire-type moves when at full HP." },
    :SAGEPOWER => { :name => "Sage Power", :pif => false, :short => "Ups Special Attack by 50% and locks move.", :full => "Boosts Special Attack by 50% but locks the user into using the first move selected until they switch out." },
    :BONEZONE => { :name => "Bone Zone", :pif => false, :short => "Bone moves ignore immunities and deal 2x on not very effective.", :full => "Bone moves bypass immunities and hit for normal damage, while resisted moves do 2x damage. Neutral/super effective moves remain unchanged." },
    :WEATHERCONTROL => { :name => "Weather Control", :pif => false, :short => "Immune to all weather-based moves.", :full => "Grants immunity to weather-based moves: Thunder, Solar Beam/Blade, Hurricane, Blizzard, Silver Wind, Weather Ball, all Storm moves (not including Magma, Leaf, or Diamond), Sheer Cold, and Pledge moves. Does not stop weather setup or damage." },
    :SPEEDFORCE => { :name => "Speed Force", :pif => false, :short => "Contact moves use 20% of its Speed stat additionally.", :full => "Adds 20% of the user's Speed stat to damage when using contact moves. Choice Scarf does not affect this ability." },
    :SEAGUARDIAN => { :name => "Sea Guardian", :pif => false, :short => "Ups highest stat by +1 on entry in rain.", :full => "When entering battle during rain, boosts the user's highest stat by one stage. Works with any rain type." },
    :MOLTENDOWN => { :name => "Molten Down", :pif => false, :short => "Fire-type is super effective against Rock-type.", :full => "Molten Down makes Fire-type moves super effective against Rock-types instead of resisted." },
    :HYPERAGGRESSIVE => { :name => "Hyper Aggressive", :pif => false, :short => "Moves hit twice. Second hit does 25% damage.", :full => "Makes all attacks hit twice in succession. The first hit deals 100%, while the second hit deals 25%. Each hit rolls secondary effects independently (except flinch)." },
    :FLOCK => { :name => "Flock", :pif => false, :short => "Boosts Flying-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Flying-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :FIELDEXPLORER => { :name => "Field Explorer", :pif => false, :short => "Boosts field moves by 50%. Cut, Surf, Strength etc.", :full => "Boosts the power of moves that can be used in the overworld by 50%. Includes all HM moves, (Zen) Headbutt, Ice Spinner, Hidden/Secret Power, and Dig." },
    :STRIKER => { :name => "Striker", :pif => false, :short => "Boosts the power of kicking moves by 1.3x.", :full => "Striker increases the power of all kicking moves by 30%. Includes Pyro Ball." },
    :FROZENSOUL => { :name => "Frozen Soul", :pif => false, :short => "Ice-type moves get +1 priority at full HP.", :full => "Frozen Soul grants +1 priority to all Ice-type moves when the user is at maximum HP." },
    :PREDATOR => { :name => "Predator", :pif => false, :short => "Dealing a KO heals 1/4 of this Pokémon's max HP.", :full => "When the user knocks out an opponent with a direct hit, it immediately recovers 25% of its maximum HP." },
    :LOOTER => { :name => "Looter", :pif => false, :short => "Dealing a KO heals 1/4 of this Pokémon's max HP.", :full => "When the user knocks out an opponent with a direct hit, it immediately recovers 25% of its maximum HP." },
    :LUNARECLIPSE => { :name => "Lunar Eclipse", :pif => false, :short => "Fairy & Dark gains STAB. Hypnosis has 1.5x accuracy.", :full => "Lunar Eclipse grants STAB bonus to both Fairy and Dark-type moves regardless of the user's typing. Improves Hypnosis accuracy to 90%." },
    :SOLARFLARE => { :name => "Solar Flare", :pif => false, :short => "Chloroplast + Immolate.", :full => "Converts Normal-type moves to Fire-type and grants Fire-type STAB. If the user is Fire-type their Fire-type moves get 10% burn chance. Additionally activates any Sun related effects for the user's moves." },
    :POWERCORE => { :name => "Power Core", :pif => false, :short => "The Pokémon uses +20% of its Defense or SpDef during moves.", :full => "Adds 20% of Defense stat to physical attacks and 20% of Special Defense stat to special attacks when calculating damage." },
    :SIGHTINGSYSTEM => { :name => "Sighting System", :pif => false, :short => "Moves always hit. Moves last for moves less than 80% accuracy.", :full => "Sighting System guarantees all moves hit regardless of accuracy checks. Moves with less than 80% base accuracy receive -3 priority." },
    :OPPORTUNIST => { :name => "Opportunist", :pif => false, :short => "+1 priority vs foes below 1/2 max HP.", :full => "Grants +1 priority to all moves when targeting opponents with 50% HP or less." },
    :GIANTWINGS => { :name => "Giant Wings", :pif => false, :short => "Boosts the power of wing, wind or air-based moves by 1.3x.", :full => "Giant Wings boosts the power of all wing, wind, and air-based moves by 30%." },
    :MOMENTUM => { :name => "Momentum", :pif => false, :short => "Contact moves use the Speed stat for damage calculation.", :full => "Contact moves use Speed stat for damage instead of Attack/Special Attack. Choice Scarf does not affect this ability." },
    :GRIPPINCER => { :name => "Grip Pincer", :pif => false, :short => "50% chance to trap. Then ignores Defense & accuracy checks.", :full => "Contact moves have a 50% chance to trap the target (like Wrap), preventing escape or switching. Against trapped targets, the user's moves ignore defensive stats changes and always hit. Trapped targets take 1/8 max HP damage each turn. Trap lasts 4-5 turns (7 with Grip Claw)." },
    :PRECISEFIST => { :name => "Precise Fist", :pif => false, :short => "Punching moves get +1 crit and 5x effect chance.", :full => "Punching moves gain +1 critical hit stage and 5x their normal secondary effect chance." },
    :DEADEYE => { :name => "Deadeye", :pif => false, :short => "Arrow & cannon moves never miss. Crits hit weakest defense.", :full => "The user is unable to miss arrow-based attacks and cannon moves (different from Mega Launcher moves, includes moves blocked by Bulletproof). Additionally, when landing critical hits, the attack targets the opponent's weaker defensive stat." },
    :ARTILLERY => { :name => "Artillery", :pif => false, :short => "Mega Launcher moves always hit and hit both foes.", :full => "Mega Launcher moves always hit and strike both opposing Pokemon simultaneously. Unable to miss with pulse, beam, ball, aura, and other blast related moves." },
    :AMPLIFIER => { :name => "Amplifier", :pif => false, :short => "Ups sound moves by 30% and makes them hit both foes.", :full => "Amplifier boosts sound-based moves by 30% damage. Single-target sound moves gain spread targeting to hit both opposing Pokemon. Does not spread with multihit moves." },
    :ICEDEW => { :name => "Ice Dew", :pif => false, :short => "Redirects Ice moves. Absorbs them, ups highest Atk.", :full => "Redirects all Ice-type moves to this Pokemon and absorbs them. Upon absorbing an Ice move, boosts either Attack or Special Attack (whichever is higher) by one stage." },
    :SUNWORSHIP => { :name => "Sun Worship", :pif => false, :short => "Ups highest stat by +1 on entry in sun.", :full => "When entering battle during sun, boosts the user's highest stat by one stage. Works with any sun type." },
    :POLLINATE => { :name => "Pollinate", :pif => false, :short => "Normal moves become Bug. Immune to powder if Bug-type.", :full => "Changes the user's Normal-type moves to Bug-type. If the user is Bug-type it is immune to powder moves, otherwise it gains Bug STAB." },
    :VOLCANORAGE => { :name => "Volcano Rage", :pif => false, :short => "Triggers 50 BP Eruption after using a Fire-type move.", :full => "After using any Fire-type move, Volcano Rage triggers a followup Eruption attack with 50 base power. Damage scales with the user's current HP percentage, having 50 BP at full health." },
    :NOSFERATU => { :name => "Nosferatu", :pif => false, :short => "Contact moves do +20% damage and heal 1/2 of damage dealt.", :full => "Moves that make contact deal an additional 20% damage and heal the user to heal for 1/2 of the damage dealt. This healing applies after all hits of multi-hit moves and after recoil is applied." },
    :SPECTRALIZE => { :name => "Spectralize", :pif => false, :short => "Normal moves become Ghost. Ghost moves are empowered.", :full => "Changes the user's Normal-type moves to Ghost-type. If the user is Ghost-type its Ghost-type moves have a 10% fear chance, otherwise it gains Ghost STAB." },
    :DISCIPLINE => { :name => "Discipline", :pif => false, :short => "Can switch while rampaging. Can't be confused or intimidated.", :full => "While using a rampage move (like Outrage or Raging Fury), the user can switch out of battle during the rampage. Immune to confusion, Intimidate, and Scare. Immediately cures confusion when receiving this ability." },
    :MIGHTYHORN => { :name => "Mighty Horn", :pif => false, :short => "Boosts the power of horn and drill-based by 1.3x.", :full => "Mighty Horn boosts the power of horn and drill-based attacks by 30%." },
    :ARCTICFUR => { :name => "Arctic Fur", :pif => false, :short => "Weakens incoming physical and special moves by 35%.", :full => "Reduces both physical and special damage by 35%. Multiplicative with other sources of damage reduction." },
    :PYROSHELLS => { :name => "Pyro Shells", :pif => false, :short => "Uses 50BP Explosion or Outburst after using Mega Launcher move.", :full => "Using a Mega Launcher move triggers a 50 BP Explosion if the move is physical or 50 BP Outburst if the move is special or status. Outburst and Explosion have no secondary effects and hit all surrounding Pokemon." },
    :FUNGALINFECTION => { :name => "Fungal Infection", :pif => false, :short => "Contact moves inflict Leech Seed on the target.", :full => "Spreads Leech Seed when using a contact move, draining 1/8th of the target's max HP at the end of each turn." },
    :SCRAPYARD => { :name => "Scrapyard", :pif => false, :short => "Sets a layer of Spikes when hit by a contact move.", :full => "Sets a layer of Spikes on the opponent's side when the user is successfully hit by a contact move. Each layer damages switching grounded Pokemon by 12.5%, 16.7%, or 25% of max HP for 1-3 layers respectively. Each hit of a multihitting attack sets a layer." },
    :LOOSEQUILLS => { :name => "Loose Quills", :pif => false, :short => "Sets a layer of Spikes when hit by a contact move.", :full => "Sets a layer of Spikes on the opponent's side when the user is successfully hit by a contact move. Each layer damages switching grounded Pokemon by 12.5%, 16.7%, or 25% of max HP for 1-3 layers respectively. Each hit of a multihitting attack sets a layer." },
    :TOXICDEBRIS => { :name => "Toxic Debris", :pif => false, :short => "Sets a layer of Toxic Spikes when hit by a contact move.", :full => "Toxic Debris automatically sets a layer of Toxic Spikes on the opponent's side when hit by a contact move. Each layer poisons switching grounded Pokemon: one layer causes regular poison, two layers cause badly poisoned. Each hit of a multihitting attack sets a layer." },
    :MINERALIZE => { :name => "Mineralize", :pif => false, :short => "Normal moves become Rock. Rock moves are empowered.", :full => "Changes the user's Normal-type moves to Rock-type. If the user is Rock-type its Rock-type moves have a 10% bleed chance, otherwise it gains Rock STAB." },
    :LOOSEROCKS => { :name => "Loose Rocks", :pif => false, :short => "Deploys Stealth Rocks when hit by a contact move.", :full => "Set Stealth Rock on the opponent's side when the user is hit by any contact move. Stealth Rock deals 1/8th of the opponent's max HP when switching. Considered Rock-type damage and is modified by type effectiveness." },
    :FEARMONGER => { :name => "Fearmonger", :pif => false, :short => "Intimidate + Scare; 10% chance to fear with contact moves.", :full => "Fearmonger lowers both Attack and Special Attack of opposing Pokemon upon entry by one stage. Additionally provides a 10% chance to inflict fear when landing contact moves." },
    :TOXICSPILL => { :name => "Toxic Spill", :pif => false, :short => "Non-Poison-types take 1/8 dmg every turn when on field.", :full => "Toxic Spill damages all non-Poison-type Pokemon by 1/8 HP each turn. Pokemon with Poison Heal recover instead. Disappears when the user leaves." },
    :DRACONIZE => { :name => "Draconize", :pif => false, :short => "Normal moves become Dragon. Dragon moves are empowered.", :full => "Changes the user's Normal-type moves to Dragon-type. If the user is Dragon-type its Dragon-type moves deal neutal damage vs Fairy, otherwise it gains Dragon STAB." },
    :PRETTYPRINCESS => { :name => "Pretty Princess", :pif => false, :short => "Does 50% more damage if the target has any lowered stat.", :full => "Pretty Princess increases the user's damage by 50% against targets with any negative stat stage." },
    :SELFREPAIR => { :name => "Self Repair", :pif => false, :short => "Self Sufficient + Natural Cure.", :full => "Recovers 1/16th of max HP at the end of the turn and cures all status conditions when switching out of battle." },
    :SWEEPINGEDGE => { :name => "Sweeping Edge", :pif => false, :short => "Keen Edge moves always hit and hit both foes.", :full => "Sweeping Edge makes all Keen Edge moves never miss and hit both opposing Pokemon in double battles. Multihit moves will only hit each target one time." },
    :EQUINOX => { :name => "Equinox", :pif => false, :short => "Boosts Atk or SpAtk to match the higher value.", :full => "Equinox chooses the higher offensive stat for each attack. If Attack is higher, physical and special moves use your Attack stat. If Special Attack is higher, physical and special moves use your Special Attack stat." },
    :ABSORBANT => { :name => "Absorbent", :pif => false, :short => "Drain moves recover +50% HP & apply Leech Seed.", :full => "Absorbent boosts HP recovery from drain moves by 50% and applies Leech Seed to the target on hit, draining the target for 1/8th of their max HP at the end of each turn." },
    :CHEAPTACTICS => { :name => "Cheap Tactics", :pif => false, :short => "Attacks with Scratch on switch-in.", :full => "Cheap Tactics uses Scratch (40 BP Normal physical move) targeting a random opponent when switching into battle." },
    :COWARD => { :name => "Coward", :pif => false, :short => "Sets up Protect on switch-in. Only works once.", :full => "Coward automatically activates Protect on entry. Works once per battle." },
    :DUALWIELD => { :name => "Dual Wield", :pif => false, :short => "Mega Launcher and Keen Edge moves hit twice for 70% damage.", :full => "Mega Launcher and Keen Edge moves that hit one time normally now hit twice, with each hit dealing 70% of the move's normal damage. Secondary effects roll independently for each hit (except flinch)." },
    :AMBUSH => { :name => "Ambush", :pif => false, :short => "Guaranteed critical hit on first turn.", :full => "Ambush guarantees a critical hit on the user's first turn after switching in or at the start of battle." },
    :ATLAS => { :name => "Atlas", :pif => false, :short => "Sets Gravity on entry for 8 turns.", :full => "Atlas sets Gravity upon entering battle for 8 turns. Gravity prevents levitating moves like Fly; grounds all Pokemon making them vulnerable to Ground moves, Arena Trap, and hazards; boosts Grav Apple's damage by 50%; and boosts move accuracy by 66%." },
    :JAWSOFCARNAGE => { :name => "Jaws of Carnage", :pif => false, :short => "KOs heal 1/4 of max HP, 1/2 if using a biting move.", :full => "Restores 50% max HP when defeating foes with biting moves or 25% with other moves. Only activates when knocking out a target with a direct hit." },
    :SHOCKINGJAWS => { :name => "Shocking Jaws", :pif => false, :short => "Biting moves have a 50% chance to inflict paralysis.", :full => "Biting moves have a 50% chance to inflict paralysis on hit. Multihits roll the activation chance on each hit." },
    :FAEHUNTER => { :name => "Fae Hunter", :pif => false, :short => "Deals 1.5x damage to Fairy. Takes 0.5x damage from Fairy.", :full => "Deals 1.5x damage to Fairy-type Pokemon and takes 0.5x damage when attacked by Fairy-type Pokemon. Based on attacker/defender Pokemon types, not move types. The damage reduction is multiplicative with other sources." },
    :GRAVITYWELL => { :name => "Gravity Well", :pif => false, :short => "Sets Gravity on entry for 5 turns.", :full => "Sets Gravity upon entering battle for 5 turns. Gravity prevents levitating moves like Fly; grounds all Pokemon making them vulnerable to Ground moves, Arena Trap, and hazards; boosts Grav Apple's damage by 50%; and boosts move accuracy by 66%." },
    :LUMBERJACK => { :name => "Lumberjack", :pif => false, :short => "Deals 1.5x damage to Grass. Takes 0.5x damage from Grass.", :full => "Deals 1.5x damage to Grass-type Pokemon and takes 0.5x damage when attacked by Grass-type Pokemon. Based on attacker/defender Pokemon types, not move types. The damage reduction is multiplicative with other sources." },
    :WELLBAKEDBODY => { :name => "Well Baked Body", :pif => false, :short => "Boosts Defense sharply instead of being hit by Fire-type moves.", :full => "Well Baked Body grants immunity to Fire-type moves and boosts Defense by 2 stages when hit by Fire attacks." },
    :EARTHEATER => { :name => "Earth Eater", :pif => false, :short => "Heals 25% of max HP when hit by a Ground-type move.", :full => "Earth Eater heals the Pokemon for 25% of its maximum HP when hit by Ground-type moves." },
    :ADRENALINERUSH => { :name => "Adrenaline Rush", :pif => false, :short => "KOs raise Speed by one stage.", :full => "Boosts the user's Speed by one stage whenever it knocks out an opponent with a direct hit." },
    :CRYOMANCY => { :name => "Cryomancy", :pif => false, :short => "Moves inflict frostbite 5x as often.", :full => "Cryomancy multiplies the chance of inflicting frostbite by 5x on all moves. Does not interact with Freezing Point." },
    :PHANTOMPAIN => { :name => "Phantom Pain", :pif => false, :short => "Ghost-type moves deal normal damage to Normal.", :full => "Phantom Pain removes Normal-type immunity to Ghost-type moves, allowing Ghost attacks to hit Normal-type Pokemon for 1x effectiveness." },
    :EMANATE => { :name => "Emanate", :pif => false, :short => "Normal moves become Psychic. Psychic moves are empowered.", :full => "Changes the user's Normal-type moves to Psychic-type. If the user is Psychic-type its Psychic-type moves have a 10% confusion chance, otherwise it gains Psychic STAB." },
    :MONKEYBUSINESS => { :name => "Monkey Business", :pif => false, :short => "Uses Tickle on entry.", :full => "Monkey Business automatically uses Tickle upon switching into battle, lowering the opposing Pokemon's Attack and Defense stats by one stage each." },
    :COMBATSPECIALIST => { :name => "Combat Specialist", :pif => false, :short => "Boosts the power of punching and kicking moves by 1.3x.", :full => "Combat Specialist boosts the power of punching and kicking moves by 30%." },
    :SUPERHOTGOO => { :name => "Super Hot Goo", :pif => false, :short => "Flame Body + Gooey.", :full => "Contact moves have a 30% chance to inflict burn and the user lowers the attacker's Speed by one stage when receiving a contact move." },
    :INVERSION => { :name => "Inversion", :pif => false, :short => "Sets up Inverse Room on entry, lasts 3 turns.", :full => "Sets up Inverse Room on entry, lasts 3 turns." },
    :ACCELERATE => { :name => "Accelerate", :pif => false, :short => "Moves that need a charge turn are now used instantly.", :full => "Accelerate eliminates the charging turn requirement for two-turn moves, allowing them to be used instantly." },
    :GENERATOR => { :name => "Generator", :pif => false, :short => "Charges up once on entry or when electric terrain is active.", :full => "Generator charges up the user once upon switching in, doubling Electric-type move power for the next Electric attack. Recharge when Electric Terrain becomes active during battle. The charged state is lost upon switching out or after using an Electric move." },
    :MOONSPIRIT => { :name => "Moon Spirit", :pif => false, :short => "Fairy & Dark gains STAB. Moonlight recovers 75% HP.", :full => "Moon Spirit grants STAB to all Fairy and Dark-type moves regardless of the user's typing. When using Moonlight, recovery increases to 75% max HP instead of normal 50% or weather-modified amounts." },
    :DUSTCLOUD => { :name => "Dust Cloud", :pif => false, :short => "Attacks with Sand Attack on switch-in.", :full => "Uses Sand Attack on the opponent upon switching into battle, reducing the target's accuracy by one stage." },
    :TRICKSTER => { :name => "Trickster", :pif => false, :short => "Uses Disable on switch-in.", :full => "Uses Disable on switch-in. Disable prevents the target from using their last-used move for 4 turns. Fails if the target has not moved yet." },
    :SANDGUARD => { :name => "Sand Guard", :pif => false, :short => "Blocks priority and reduces special damage by 1/2 in sand.", :full => "Sand Guard blocks priority moves and reduces Special Attack damage by 50% during a sandstorm. Multiplicative with other sources of damage reduction." },
    :NATURALRECOVERY => { :name => "Natural Recovery", :pif => false, :short => "Natural Cure + Regenerator.", :full => "Cures all status conditions when switching out. Also restores 33% of maximum HP when switching out." },
    :WINDRIDER => { :name => "Wind Rider", :pif => false, :short => "Increases attack in tailwind or when hit by wind move.", :full => "Boosts the user's highest attacking stat when entering battle under Tailwind. When hit by wind-based moves, absorbs the attack and raises the highest attacking stat by one stage." },
    :SOOTHINGAROMA => { :name => "Soothing Aroma", :pif => false, :short => "Cures party status on entry.", :full => "On entry, heals all status conditions from every Pokemon in the user's party, including both active and benched Pokemon." },
    :PRIMANDPROPER => { :name => "Prim and Proper", :pif => false, :short => "Wonder Skin + Cute Charm.", :full => "When hit by making contact (offensively or defensively), has a 50% chance to infatuate the attacker (cuts their Attack and Special Attack in half). Only works on Pokemon of the opposite gender. Immune to all damage boosting ability effects from opponents, other than Parental Bond and Multi-Headed." },
    :TIPPINGPOINT => { :name => "Tipping Point", :pif => false, :short => "Getting hit raises SpAtk. Critical hits maximize SpAtk.", :full => "When hit, raises the user's Special Attack by 1 stage or maximizes it on critical hits. Activates on each hit of a multihit move." },
    :AFTERSHOCK => { :name => "Aftershock", :pif => false, :short => "Triggers Magnitude 4-7 after using a damaging move.", :full => "After landing a damaging move, the user follows up with Magnitude at 10, 30, 50, or 70 power. Hits all adjacent Pokemon." },
    :FREEZINGPOINT => { :name => "Freezing Point", :pif => false, :short => "20% frostbite chance on contact, 30% chance on non-contact.", :full => "Contact with this Pokemon has a 20% chance to inflict frostbite. Non-contact has a 30% chance. Works offensively and defensively. Frostbitten Pokemon lose 1/8th of their max HP each turn and have their Special Attack halved." },
    :DOOMBRINGER => { :name => "Doombringer", :pif => false, :short => "Uses Doom Desire on switch-in.", :full => "Uses Doom Desire on entry. Doom Desire is a Steel-type 140 base power and strikes the target two turns later, bypassing substitutes and other protections. The attack cannot miss once initiated and ignores accuracy checks. This cannot target the same Pokemon twice." },
    :WISHMAKER => { :name => "Wishmaker", :pif => false, :short => "Uses Wish on switch-in. Three uses per battle.", :full => "Uses Wish on entry, setting up delayed healing that restores half of the current ally's max HP on the following turn. Activates 3 times per battle." },
    :SUPPRESS => { :name => "Suppress", :pif => false, :short => "Casts Torment on entry.", :full => "Uses Torment on entry, preventing the opponent from using the same move consecutively." },
    :HEAVENASUNDER => { :name => "Heaven Asunder", :pif => false, :short => "Spacial Rend always crits. Ups crit level by +1.", :full => "Guarantees Spacial Rend always lands critical hits and increases critical hit ratio by one stage for all other moves." },
    :DETERMINATION => { :name => "Determination", :pif => false, :short => "Ups Special Attack by 50% if statused.", :full => "Boosts Special Attack stat by 50% when the Pokemon has any status condition. Also prevents the frostbite status from reducing Special Attack." },
    :PURELOVE => { :name => "Pure Love", :pif => false, :short => "Cute Charm + heal 25% damage vs infatuated.", :full => "50% to infatuate on contact (cuts their Attack and Special Attack in half). Heals 25% of damage dealt when attacking infatuated targets." },
    :FIGHTER => { :name => "Fighter", :pif => false, :short => "Boosts Fight.-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Fighting-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :TELEKINETIC => { :name => "Telekinetic", :pif => false, :short => "Casts Telekinesis on entry.", :full => "Casts Telekinesis on entry. All moves against the target cannot miss, but they become immune to Ground-type moves and other Grounded effects. Cannot affect Rooted Pokemon or if they hold Iron Ball. Wears off under Gravity or if they are hit by Smack Down. Lasts 3 turns." },
    :COMBUSTION => { :name => "Combustion", :pif => false, :short => "Boosts the power of Fire-type moves by 1.5x.", :full => "Combustion increases the power of all Fire-type moves by 50%." },
    :POWDERBURST => { :name => "Powder Burst", :pif => false, :short => "Casts Powder on entry.", :full => "Uses Powder on entry, coating the target with explosive powder for the remainder of the turn. If the target uses any Fire-type move while coated, they lose 25% of their max HP and the powder is consumed." },
    :RETRIEVER => { :name => "Retriever", :pif => false, :short => "Retrieves item on switch-out.", :full => "Retrieves original held item when switching out if not holding one. Must not be knocked out to activate." },
    :MONSTERMASH => { :name => "Monster Mash", :pif => false, :short => "Casts Trick-or-Treat on entry.", :full => "Casts Trick-or-Treat on entry, adding Ghost type to the target. They do not benefit from the effects of fog. The effect persists until the target switches out." },
    :TWOSTEP => { :name => "Two Step", :pif => false, :short => "Triggers 50BP Revelation Dance after using a Dance move.", :full => "After using a dance move, automatically follows up with a 50 BP Revelation Dance. The follow-up move matches the user's primary type." },
    :FORTITUDE => { :name => "Fortitude", :pif => false, :short => "Boosts Sp. Def +1 when hit. Critical hits maximize Sp. Def.", :full => "When hit, raises the user's Special Defense by 1 stage or maximizes it on critical hits. Activates on each hit of a multihit move." },
    :GRAPPLER => { :name => "Grappler", :pif => false, :short => "Trapping moves last 6 turns. Trapping deals 1/6 HP.", :full => "Trapping moves last 6 turns instead of 4-5 turns and increases their damage at the end of the turn to 1/6 max HP per turn." },
    :BERSERKDNA => { :name => "Berserk DNA", :pif => false, :short => "On entry, ups highest attacking stat by +2 but enrages.", :full => "Raises the user's highest attacking stat by 2 stages when it enters, but becomes enraged, adding 33% recoil to all attacks. Boost applies even if it can't become enraged." },
    :HUBRIS => { :name => "Hubris", :pif => false, :short => "KOs raise SpAtk by one stage.", :full => "Boosts the user's Special Attack by one stage whenever it knocks out an opponent with a direct hit." },
    :CHROMECOAT => { :name => "Chrome Coat", :pif => false, :short => "Take 40% less spec. dmg, but Speed x0.9. Triple user's weight.", :full => "Chrome Coat reduces special damage by 40% but decreases Speed by 10%. Also triples the user's weight. The damage reduction is multiplicative with other sources." },
    :WEBSPINNER => { :name => "Web Spinner", :pif => false, :short => "Uses String Shot on switch-in.", :full => "Uses String Shot on switch in, harshly lowering the Speed of all opponents by 2 stages." },
    :SALTCIRCLE => { :name => "Salt Circle", :pif => false, :short => "Prevents opposing pokemon from fleeing on entry.", :full => "Prevents all opposing Pokemon from fleeing or switching when user enters battle. Effect lasts until user leaves field. Forced switches and pivot moves like Flip Turn still work." },
    :GUARDDOG => { :name => "Guard Dog", :pif => false, :short => "Can't be forced to switch out. Inverts Intimidate effects.", :full => "Guard Dog prevents forced switching from moves and Red Card. When affected by Intimidate or Scare, it raises the stat by one stage instead of lowering it." },
    :EGOIST => { :name => "Egoist", :pif => false, :short => "Raises its own stats when foes raise theirs.", :full => "Egoist copies stat boosts that enemy Pokemon receive and applies them to itself. Does not copy other Egoist boosts." },
    :SUBDUE => { :name => "Subdue", :pif => false, :short => "Doubles stat drop effects used by this pokemon.", :full => "Doubles the effectiveness of stat drops from moves. Does not affect self-inflicted stat drops or enemy abilities." },
    :READIEDACTION => { :name => "Readied Action", :pif => false, :short => "Doubles attack on first turn.", :full => "Increases the user's Attack stat by 2x for one turn. Multiplicative with other damage boosts. Reapplies after switching in." },
    :GUILTTRIP => { :name => "Guilt Trip", :pif => false, :short => "Sharply lowers attacker's Attack and SpAtk when fainting.", :full => "The attacker that delivers the final blow on the user drops their Attack and Special Attack by 2 stages. Only works when fainting from direct damage." },
    :CUDCHEW => { :name => "Cud Chew", :pif => false, :short => "Eats berries again at the end of the next turn.", :full => "When consuming a berry, the user re-consumes it at the end of the following turn." },
    :MINDCRUNCH => { :name => "Mind Crunch", :pif => false, :short => "Biting moves use Special Attack and deal 30% more damage.", :full => "Biting moves use the Special Attack (still targets enemy's Defense unless stated otherwise) and deal 30% more damage." },
    :ILLWILL => { :name => "Ill Will", :pif => false, :short => "Deletes the PP of the move that faints this Pokemon.", :full => "Ill Will drains the PP of the move that defeats the user. Has to be a direct hit." },
    :RAPIDRESPONSE => { :name => "Rapid Response", :pif => false, :short => "Boosts Speed by 50% + SpAtk by 20% on first turn.", :full => "The user gains a 50% Speed boost and 20% Special Attack boost on their first turn after switching in." },
    :THICKSKIN => { :name => "Thick Skin", :pif => false, :short => "Takes 35% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 35%. Multiplicative with other sources of damage reduction." },
    :SUNBASKING => { :name => "Sun Basking", :pif => false, :short => "Blocks priority and reduces physical damage by 1/2 in sun.", :full => "Blocks priority moves and reduces physical attack damage by 50% in sun. Multiplicative with other sources of damage reduction." },
    :CATASTROPHE => { :name => "Catastrophe", :pif => false, :short => "Sun boosts Water. Rain boosts Fire.", :full => "In Sun, Water moves gain the damage boost they receive from rain. In Rain, Fire moves gain the damage boost they receive from sun." },
    :FLOURISH => { :name => "Flourish", :pif => false, :short => "Boosts Grass moves by 50% in grassy terrain.", :full => "Boosts Grass-type moves by 50% when Grassy Terrain is active." },
    :AERIALIST => { :name => "Aerialist", :pif => false, :short => "Levitate + Flock.", :full => "The user is immune to Ground-type moves and other ground effects such as Spikes and terrains. Boosts the damage of Flying-type moves by 25%. Additionally, boosts the power of Flying-type moves by another 20%, or by 50% at 1/3 HP or lower." },
    :PARASITICSPORES => { :name => "Parasitic Spores", :pif => false, :short => "Deals 1/8 HP damage to non-Ghost. Spreads on contact.", :full => "Gain parasitic spores on entry. Each turn, affected Pokemon lose 1/8 max HP (Ghost types immune). When using contact moves, spread spores to the target. Spores persist until switch-out." },
    :ROCKHARDWILL => { :name => "Rockhard Will", :pif => false, :short => "Boosts Rock-type moves by 1.2x, or 1.5x when under 1/3 HP.", :full => "Boosts the power of Rock-type moves by 20%, or by 50% at 1/3 HP or lower." },
    :LOWVISIBILITY => { :name => "Low Visibility", :pif => false, :short => "Summons fog on entry. Lasts 8 turns.", :full => "Summons Eerie Fog upon entry, lasting 8 turns (12 with Smoke Ball). Fog reduces stat buffs from non-Ghost/Psychic-types by 1 each turn, halves weather-based recovery, grants Ghost/Psychic-types +20% damage reduction from moves, and turns all Curses into the Ghost-type Curse." },
    :ECTOPLASM => { :name => "Ectoplasm", :pif => false, :short => "Ups highest attacking stat by 1.5x in fog.", :full => "Boosts the Pokemon's highest attacking stat by 50% during fog." },
    :SURPRISE => { :name => "Surprise!", :pif => false, :short => "Astonishes enemy priority users in fog.", :full => "In fog, counters priority moves with Astonish, a 40 BP Ghost-type attack with +3 priority and always flinches. This ability will activate before the opponent's priority move comes out." },
    :ETHEREALRUSH => { :name => "Ethereal Rush", :pif => false, :short => "This Pokémon's Speed gets a 1.5x boost in fog.", :full => "Boosts the Pokemon's Speed stat by 50% during fog." },
    :SHALLOWGRAVE => { :name => "Shallow Grave", :pif => false, :short => "Revives at 25% HP once after fainting in fog.", :full => "After fainting while fog is active, the user revives at 25% max Hp when sending out your next party member. This still activates when the user faints on the last turn of fog being active." },
    :ONTHEPROWL => { :name => "On the Prowl", :pif => false, :short => "+1 priority for the first turn. Negative priority becomes +0.", :full => "All moves with priority 0 or higher gain +1 priority on the user's first turn. Negative priority moves become priority 0 instead of adding +1 priority." },
    :PRETENTIOUS => { :name => "Pretentious", :pif => false, :short => "Dealing a KO raises Crit by one stage.", :full => "Boosts the user's critical hit ratio by one stage whenever it knocks out an opponent with a direct hit." },
    :RESTINPEACE => { :name => "Rest in Peace", :pif => false, :short => "Heals 1/8 of max HP every turn in fog.", :full => "Restores 1/8 of the user's maximum HP at the end of each turn while in fog." },
    :SMOKEYMANEUVERS => { :name => "Smokey Maneuvers", :pif => false, :short => "Evasion is boosted by 1.25x in fog.", :full => "Fog reduces incoming move accuracy targeting the user by 25%." },
    :TAG => { :name => "Tag", :pif => false, :short => "Attacks switching opponents with a 20BP Pursuit.", :full => "When an enemy attempts to switch out, automatically trigger a 20 BP Pursuit to prevent them from leaving." },
    :IMPOSINGWINGS => { :name => "Imposing Wings", :pif => false, :short => "Giant Wings + Levitate.", :full => "Boosts the power of all wing, wind, and air-based moves by 30%. The user is immune to Ground-type moves and other ground effects such as Spikes or terrains, and boosts the power of Flying-type moves by 25%." },
    :WHIPLASH => { :name => "Whiplash", :pif => false, :short => "Physical attacks lower defense.", :full => "Lowers the target's Defense by one stage when hitting with physical attacks. Each target can only be affected once per turn. The Defense drop occurs after damage." },
    :RAZORSHARP => { :name => "Razor Sharp", :pif => false, :short => "Critical hits also inflict bleeding.", :full => "Inflict bleed when landing a critical hit. Bleeding causes 1/16 max HP damage per turn, prevents healing, and negates the effects of stat stages. Rock and Ghost types are immune to bleeding." },
    :DEEPCUTS => { :name => "Deep Cuts", :pif => false, :short => "Slashing moves have a 50% chance to inflict bleeding.", :full => "Keen Edge have a 50% chance to inflict bleeding on hit. Bleeding causes 1/16 max HP damage per turn, prevents healing, and negates the effects of stat stages. Rock and Ghost types are immune to bleeding.immune to bleeding. Multihits roll the activation chance on each hit." },
    :BREAKWATER => { :name => "Breakwater", :pif => false, :short => "Swift Swim + Stall.", :full => "Boosts Speed by 50% during rain. Reduces damage by 30% when moving before the opponent. Works when the user switches in mid-turn." },
    :MAGICALFISTS => { :name => "Magical Fists", :pif => false, :short => "Punching moves use Special Attack and deal 30% more damage.", :full => "Punching moves use the Special Attack (still targets enemy's Defense unless stated otherwise) and deal 30% more damage." },
    :CUTTHROAT => { :name => "Cutthroat", :pif => false, :short => "First Keen Edge move each entry gets +1 priority.", :full => "On entry, gives +1 priority to the first Keen Edge move used. Priority boost is consumed after landing any Keen Edge move. Resets ability if Sharpen is used." },
    :NEUROTOXIN => { :name => "Neurotoxin", :pif => false, :short => "Inflicting poison also lowers Attack, SpAtk, and Speed.", :full => "When inflicting poison on an opponent, drop their Attack, Special Attack, and Speed by one stage immediately after it applies." },
    :POSEIDONSDOMINION => { :name => "Poseidon's Dominion", :pif => false, :short => "Attacks with Whirlpool on entry.", :full => "Uses Whirlpool upon switching into battle, a 50 BP Water-type Special move that traps the opponent for 4-5 turns. The target takes 1/8 max HP damage each turn and cannot switch out until the trap ends." },
    :LULLABY => { :name => "Lullaby", :pif => false, :short => "Sing accuracy is 90% when used by this Pokémon.", :full => "Boosts Sing's accuracy to 90%. Does not lock to accuracy to 90%, the move still gets affected by accuracy/evasiveness changes." },
    :DEADLYPRECISION => { :name => "Deadly Precision", :pif => false, :short => "Super-effective moves never miss and ignore abilities.", :full => "Always land super effective attacks on the opponent. Allows super effective attacks to ignore the target's abilities and innates that interfere with effects or reduce damage." },
    :DEVIATE => { :name => "Deviate", :pif => false, :short => "Normal moves become Dark. Dark moves are empowered.", :full => "Changes the user's Normal-type moves to Dark-type. If the user is Dark-type its Dark-type moves have a 10% enrage chance, otherwise it gains Dark STAB." },
    :SUNSBOUNTY => { :name => "Sun's Bounty", :pif => false, :short => "Leaf Guard + Harvest.", :full => "During sun, cures all status conditions at at the end of the turn; and 50% chance to restore berry on turn end, 100% in sun. Includes berries that were used for Fling, Natural Gift, or eaten." },
    :RITEOFSPRING => { :name => "Rite Of Spring", :pif => false, :short => "Chlorophyll + Solar Power.", :full => "Boosts the user's Speed and highest attacking stat by 50% when sun is active." },
    :FIREFIGHTER => { :name => "Firefighter", :pif => false, :short => "Deals 1.5x damage to Fire. Takes 0.5x damage from Fire.", :full => "Deals 1.5x damage to Fire-type Pokemon and takes 0.5x damage when attacked by Fire-type Pokemon. Based on attacker/defender Pokemon types, not move types. The damage reduction is multiplicative with other sources." },
    :BLUR => { :name => "Blur", :pif => false, :short => "Uses Speed as defensive stat when hit by contact.", :full => "When hit by contact moves, the Pokemon uses its Speed stat instead of Defense or Special Defense for damage calculations. Choice Scarf does not affect this ability." },
    :ELUDE => { :name => "Elude", :pif => false, :short => "Uses Speed as defensive stat when hit by non-contact.", :full => "When hit by non-contact moves, the Pokemon uses its Speed stat instead of Defense or Special Defense for damage calculations. Choice Scarf does not affect this ability." },
    :MIXEDMARTIALARTS => { :name => "Mixed Martial Arts", :pif => false, :short => "Normal moves are flagged as Punch + Kick moves.", :full => "Converts all Normal-type moves into Iron Fist and Striker moves, enabling them to benefit from related abilities and interactions." },
    :CHILLINGPRESENCE => { :name => "Chilling Presence", :pif => false, :short => "Attacks with 10BP Icy Wind on switch-in.", :full => "Uses a 10BP Icy Wind (Ice, Special, Air-based) on entry, hitting all opponents and lowering their Speed by 1 stage." },
    :FROSTBIND => { :name => "Frostbind", :pif => false, :short => "Inflicting Frostbite also inflicts Disable.", :full => "When inflicting frostbite, the user also inflicts disable. Disable prevents the target from using their last-used move for 4 turns. Fails if the target has not moved yet." },
    :GLACIALGHOST => { :name => "Glacial Ghost", :pif => false, :short => "Slush Rush + Snow Cloak.", :full => "Boosts the Pokemon's Speed by 50% and its evasion by 25% during hail. Immune to hail damage." },
    :TEMPORALRUPTURE => { :name => "Temporal Rupture", :pif => false, :short => "Roar of Time is altered drastically.", :full => "Roar of Time becomes a 100 BP +0 Priority attack that changes the target's Ability to Slow Start (halves attacking stats and speed for 5 turns) but no longer forces the target to switch." },
    :GRASSFLUTE => { :name => "Grass Flute", :pif => false, :short => "Sound moves inflict Fear.", :full => "Sound moves inflict Fear on hit. Fear traps the target for 2 turns and they take 50% more damage. If forced out by moves like Whirlwind, the target loses Fear." },
    :HEMOTOXIN => { :name => "Hemotoxin", :pif => false, :short => "Suppresses abilities of the target when they're poisoned.", :full => "Negates the opponent's ability and innates when the user successfully poisons them. Suppression wears off after they switch out." },
    :TOXICSURGE => { :name => "Toxic Surge", :pif => false, :short => "Casts Toxic Terrain on entry. Lasts 8 turns.", :full => "Sets Toxic Terrain on switch-in for 8 turns (12 with Terrain Extender). While active, grounded Pokemon that aren't Poison or Steel-type take 1/16 max HP damage each turn, Poison-type moves deal 30% more damage, and Spikes are converted to Toxic Spikes." },
    :BIOFILM => { :name => "Biofilm", :pif => false, :short => "Boosts Special Defense by 50% in Toxic Terrain.", :full => "Boosts the user's Special Defense stat by 50% when in Toxic Terrain." },
    :HEATSINK => { :name => "Heat Sink", :pif => false, :short => "Redirects Fire moves. Absorbs them, ups highest Atk.", :full => "Draws in Fire-type moves and gain immunity to them. Additionally, Fire-type moves boost the highest attacking stat of the user by one stage." },
    :RELICSTONE => { :name => "Relic Stone", :pif => false, :short => "Other battlers don't benefit from STAB.", :full => "While the user is on field, every other Pokemon does not receive a STAB bonus from typing or abilities." },
    :ENERGYTAP => { :name => "Energy Tap", :pif => false, :short => "Heals the user for 1/8 of the damage they deal.", :full => "Heals the user for 1/8 of all damage they deal to opponents. Healing occurs immediately after damage is dealt. Minimum healing of 1 HP." },
    :REVELATION => { :name => "Revelation", :pif => false, :short => "Changes into Revelation form until 1/4 HP or less.", :full => "Changes into Revelation form until 1/4 HP or less." },
    :RAGINGSTORM => { :name => "Raging Storm", :pif => false, :short => "Ups highest attacking stat by 1.5x in rain.", :full => "Ups highest attacking stat by 1.5x in rain." },
    :ECHOLOCATION => { :name => "Echolocation", :pif => false, :short => "In fog, deal 20% more damage and never miss.", :full => "In fog, deal 20% more damage and never miss." },
    :RAINSHROUD => { :name => "Rain Shroud", :pif => false, :short => "Evasion is boosted by 1.3x in rain.", :full => "Evasion is boosted by 1.3x in rain." },
    :CURLIPEDE => { :name => "Curlipede", :pif => false, :short => "Let's Roll + Coil Up", :full => "Let's Roll automatically raises Defense by one stage and applies the Defense Curl status upon entering battle, doubling the power of Rollout and other rolling moves. On entry, gives +1 priority to the first biting move used. Priority boost is consumed after landing any biting move.\n\nLet's Roll: Let's Roll automatically raises Defense by one stage and applies the Defense Curl status upon entering battle, doubling the power of Rollout and other rolling moves.\n\nCoil Up: On entry, gives +1 priority to the first biting move used. Priority boost is consumed after landing any biting move." },
    :THIRDDEGREEBURN => { :name => "Third-Degree Burn", :pif => false, :short => "Can burn any type. Fire-type moves ignore abilities.", :full => "This Pokemon can burn Fire-Type Pokemon regardless of immunities to burn. Fire-type moves ignore the target's abilities and innates that interfere with effects or reduce damage." },
    :PRIMORDIALSEA => { :name => "Primordial Sea", :pif => true, :short => "Heavy Rain until switched out. Fire-type moves are unusable.", :full => "Creates Heavy Rain that lasts until user switches. Completely nullifies all damaging Fire moves. Water moves gain 50% boost. Cannot be overridden except by other primal weather. Activates extra effects on rain related moves. Halves the effectiveness of sun related moves." },
    :DESOLATELAND => { :name => "Desolate Land", :pif => true, :short => "Intense Sun until switched out. Water-type moves are unusable.", :full => "Creates Extremely Harsh Sunlight lasting until user switches. Completely nullifies all damaging Water moves. Fire moves gain 50% boost. Cannot be overridden except by other primal weather. Activates extra effects on sun related moves." },
    :DELTASTREAM => { :name => "Delta Stream", :pif => true, :short => "Strong Winds until switched out. Weather-based moves not usable.", :full => "Creates Strong Winds lasting until user switches. Reduces super-effective damage to all active Flying-types to neutral. Blocks all weather-based moves from hitting opponents. Cannot be overridden except by other primal weather." },
    :INTREPIDSWORD => { :name => "Intrepid Sword", :pif => false, :short => "On entry, raises Attack by one stage.", :full => "Intrepid Sword raises the Pokemon's Attack stat by one stage when switching into battle." },
    :UNSEENFIST => { :name => "Unseen Fist", :pif => false, :short => "Contact moves strike through protection.", :full => "Unseen Fist allows all contact moves to bypass protection moves and ignore any secondary effects associated with them." },
    :CRYSTALLIZE => { :name => "Crystallize", :pif => false, :short => "Rock-type moves become Ice and get a 1.1x boost.", :full => "Crystallize converts all Rock-type moves to Ice-type and boosts their power by 10%." },
    :BIGLEAVES => { :name => "Big Leaves", :pif => false, :short => "Chloroplast + Chlorophyll + Leaf Guard + Harvest + Solar Power.", :full => "Activates any sun related effects for the user's moves. Boosts Speed stat by 50% in sun. Cures status in sun. 50% chance to restore berry on turn end, 100% in sun. Raises highest attacking stat by 50% in sun." },
    :COLDREBOUND => { :name => "Cold Rebound", :pif => false, :short => "Attacks with Icy Wind when hit by a contact move.", :full => "When struck by any contact move, Cold Rebound retaliates with Icy Wind (60 BP), lowering the attacker's Speed by one stage." },
    :SPECTRALSHROUD => { :name => "Spectral Shroud", :pif => false, :short => "Spectralize + moves have 30% chance to badly poison the foe.", :full => "Changes the user's Normal-type moves to Ghost-type. If the user is Ghost-type its Ghost-type moves have a 10% fear chance, otherwise it gains Ghost STAB. Its moves, including status moves, have a 30% chance to badly poison the target." },
    :THUNDERCALL => { :name => "Thundercall", :pif => false, :short => "Triggers Smite at 20% power when using an Electric move.", :full => "After using any Electric-type move, Thundercall automatically triggers a follow-up Smite attack at 20% power (24 base power). This physical Electric attack has an 80% accuracy, can paralyze targets (20% chance), and applies the Smack Down effect - grounding Flying-types." },
    :MARINEAPEX => { :name => "Marine Apex", :pif => false, :short => "50% more damage to Water-types + Infiltrator.", :full => "Deal 1.5x damage to Water-type Pokemon and bypass defensive screens (Light Screen, Reflect, Aurora Veil)/Substitutes." },
    :HARDENEDSHEATH => { :name => "Hardened Sheath", :pif => false, :short => "Raises Attack by +1 when the user's horn moves hit.", :full => "Every successful horn-based attack raises Attack by one stage after it lands." },
    :STEELBARREL => { :name => "Steel Barrel", :pif => false, :short => "Immune to recoil damage, but not immune to Explosion/crash dmg.", :full => "Prevents all recoil damage from the user's moves and abilities. Also grants immunity to enrage recoil damage. Does not prevent crash damage or Explosion/Self-Destruct damage." },
    :PARRY => { :name => "Parry", :pif => false, :short => "Uses 20BP Mach Punch when hit by contact. Takes 20% less damage.", :full => "Reduces all damage by 20%. Multiplicative with other damage reduction sources. Counters contact moves with Mach Punch at 20 BP." },
    :ROUNDHOUSE => { :name => "Roundhouse", :pif => false, :short => "Kicks always hit. Damages foes' weaker defenses.", :full => "Roundhouse makes all kicking moves never miss and target the opponent's weaker defense stat." },
    :SPINNINGTOP => { :name => "Spinning Top", :pif => false, :short => "Fighting moves up speed +1 and clear hazards.", :full => "Spinning Top grants +1 Speed and removes all entry hazards from the user's side when using Fighting-type moves." },
    :KINGSWRATH => { :name => "King's Wrath", :pif => false, :short => "Lowering any stats on its side raises Atk and Def.", :full => "King's Wrath triggers when the user or their ally has their stats lowered, immediately boosting the user's Attack and Defense by one stage. Does not activate from self drops." },
    :QUEENSMOURNING => { :name => "Queen's Mourning", :pif => false, :short => "Lowering any stats on its side raises SpAtk and SpDef.", :full => "Queen's Mourning triggers when the user or their ally has their stats lowered, immediately boosting the user's Special Attack and Special Defense by one stage. Does not activate from self drops." },
    :DESERTCLOAK => { :name => "Desert Cloak", :pif => false, :short => "Protects its side from status and secondary effects in sand.", :full => "All allies become immune to status conditions and secondary effects from enemy moves while sand is active." },
    :ATOMICBURST => { :name => "Atomic Burst", :pif => false, :short => "Electromorphosis + Galvanize.", :full => "When hit by any move, the user becomes charged up, doubling the power of the next Electric-type move used. Converts all Normal-type moves into Electric-type moves and grants STAB for Electric-type moves. If they are Electric-type their Electric moves have a 10% paralysis chance." },
    :HELLBLAZE => { :name => "Hellblaze", :pif => false, :short => "Boosts Fire-type moves by 1.3x, or 1.8x when under 1/3 HP.", :full => "Boosts the power of Fire-type moves by 30%, or by 80% at 1/3 HP or lower." },
    :RIPTIDE => { :name => "Riptide", :pif => false, :short => "Boosts Water-type moves by 1.3x, or 1.8x when under 1/3 HP.", :full => "Boosts the power of Water-type moves by 30%, or by 80% at 1/3 HP or lower." },
    :FORESTRAGE => { :name => "Forest Rage", :pif => false, :short => "Boosts Grass-type moves by 1.3x, or 1.8x when under 1/3 HP.", :full => "Boosts the power of Grass-type moves by 30%, or by 80% at 1/3 HP or lower." },
    :PRIMALMAW => { :name => "Primal Maw", :pif => false, :short => "Biting moves hit twice. 2nd hit does 0.4x damage.", :full => "Primal Maw causes all biting moves to hit twice. The first hit deals 100% damage while the second hit deals 40% damage. Independently rolls secondary effects of attacks on each hit (except flinch)." },
    :GIFTEDMIND => { :name => "Gifted Mind", :pif => false, :short => "Nulls Psychic weakness; status moves always hit.", :full => "Gifted Mind grants immunity to Dark, Ghost, and Bug-type moves while making all status moves used by this Pokemon never miss. This immunity ignores Inverse Room." },
    :HYDROCIRCUIT => { :name => "Hydro Circuit", :pif => false, :short => "Electric moves +50%; Water moves siphon 25% damage.", :full => "Hydro Circuit boosts Electric-type moves by 50% and heals the user for 25% of damage dealt when using Water-type moves." },
    :CLUELESS => { :name => "Clueless", :pif => false, :short => "Negates Weather, Rooms and Terrains.", :full => "Clueless negates all weather, terrain, and room effects while active on the field." },
    :CHEATINGDEATH => { :name => "Cheating Death", :pif => false, :short => "Gets no damage for the first two hits.", :full => "Negates the first two instances of damage received. Moves still connect and secondary effects apply, but damage becomes 0." },
    :DUNETERROR => { :name => "Dune Terror", :pif => false, :short => "Sand reduces damage by 35%. Boosts Ground moves by 20%.", :full => "Dune Terror reduces damage taken by 35% during a sandstorm and boosts Ground-type moves by 20%. Damage reduction is multiplicative with other sources." },
    :INFERNALRAGE => { :name => "Infernal Rage", :pif => false, :short => "Fire-type moves deal 1.35x damage but have 5% recoil.", :full => "Infernal Rage boosts Fire-type moves by 35% but inflicts 5% recoil damage after using them. Recoil is calculated from damage dealt with minimum of 1 HP lost. This recoil cannot knock the user out." },
    :RADIANCE => { :name => "Radiance", :pif => false, :short => "1.2x accuracy. Dark moves fail when user is present.", :full => "Radiance increases the user's accuracy by 20% for all moves and causes Dark moves to fail." },
    :ANGELSWRATH => { :name => "Angel's Wrath", :pif => false, :short => "Drastically alters all of the users moves.", :full => "Tackle Encores+Disables, String Shot sets all hazards, Harden omniboosts by one stage, Iron Defense becomes a King's Shield that drops all stats, Electroweb traps, Bug Bite heals damage dealt, Poison Sting badly poisons+is super-effective on Steel. All enhanced attacks get a large damage boost." },
    :EVAPORATE => { :name => "Evaporate", :pif => false, :short => "Takes no damage and sets Mist if hit by water.", :full => "Evaporate negates all damage from Water-type moves and sets Mist for 5 turns on the user's side when hit by Water moves. Mist protects the entire team from stat reductions, including self drops." },
    :ELECTROMORPHOSIS => { :name => "Electromorphosis", :pif => false, :short => "Charges up when getting hit.", :full => "When hit by any move, the user becomes charged up, doubling the power of the next Electric-type move used. Charged status is consumed after one Electric move use." },
    :PURGATORY => { :name => "Purgatory", :pif => false, :short => "Boosts Ghost-type moves by 1.3x, or 1.8x when under 1/3 HP.", :full => "Boosts the power of Ghost-type moves by 30%, or by 80% at 1/3 HP or lower." },
    :HUNTERSHORN => { :name => "Hunter's Horn", :pif => false, :short => "Boost horn moves and heals 1/4 HP when defeating an enemy.", :full => "Boosts the power of horn and drill-based attacks by 30%. When the user knocks out an opponent with a direct hit, it immediately recovers 25% of its maximum HP." },
    :MAGMAEATER => { :name => "Magma Eater", :pif => false, :short => "Predator + Molten Down.", :full => "When the user knocks out an opponent with a direct hit, it immediately recovers 25% of its maximum HP. Fire-type are moves super effective against Rock-types instead of resisted." },
    :BERSERKERRAGE => { :name => "Berserker Rage", :pif => false, :short => "Tipping Point + Rampage.", :full => "When hit, raises the user's Special Attack by 1 stage or maximizes it on critical hits. When the user knocks out an opponent, it instantly recovers from recharge status, allowing immediate use of moves like Hyper Beam without waiting." },
    :ENLIGHTENED => { :name => "Enlightened", :pif => false, :short => "Emanate + Inner Focus.", :full => "Converts all Normal-type moves to Psychic-type and grants STAB for Psychic moves, regardless of the user's type. Focus Blast never misses. Unaffected by flinch, Intimidate, or Scare." },
    :PEACEFULSLUMBER => { :name => "Peaceful Slumber", :pif => false, :short => "Sweet Dreams + Self Sufficient.", :full => "Sweet Dreams restores 1/8 of maximum HP at the end of each turn when the user is asleep or has the Comatose ability. Additionally, it grants immunity to Bad Dreams damage. Restores 1/16 of the Pokemon's maximum HP at the end of each turn." },
    :CRYOPROFICIENCY => { :name => "Cryo Proficiency", :pif => false, :short => "Sets hail when hit + Freezing Point.", :full => "Contact with this Pokemon has a 30% chance to inflict frostbite. Non-contact has a 20% chance. Works offensively and defensively. Frostbitten Pokemon lose 1/8th of their max HP each turn and have their Special Attack halved. Sets hail after receiving a hit. Immune to hail damage." },
    :ARCANEFORCE => { :name => "Arcane Force", :pif => false, :short => "All moves gain STAB. Ups “supereffective” by 10%.", :full => "Grants the 1.5x STAB damage bonus to all moves regardless of type matching. Does not boost moves that already receive a STAB bonus. Additionally, boosts the power of super effective moves by 10%." },
    :YUKIONNA => { :name => "Yuki Onna", :pif => false, :short => "Intimidate + Scare. 30% chance to infatuate on contact.", :full => "Lowers both Attack and Special Attack of opposing Pokemon upon entry by one stage. Additionally provides a 30% chance to infatuate (cuts their Attack and Special Attack in half) the target on contact. Works offensively and defensively." },
    :MYSTICBLADES => { :name => "Mystic Blades", :pif => false, :short => "Keen Edge moves become special and deal 30% more damage.", :full => "Keen Edge moves become Special (deal Special damage and use the Special Attack stat) and deal 30% more damage." },
    :EARLYGRAVE => { :name => "Early Grave", :pif => false, :short => "Ghost-type moves get +1 priority at full HP.", :full => "Ghost-type moves gain +1 priority when at full HP." },
    :PERMANENCE => { :name => "Permanence", :pif => false, :short => "Foes can't heal in any way.", :full => "Prevents all opposing Pokemon from healing through any means. Blocks healing moves like Recover, absorbing moves like Drain Punch, passive healing from Leftovers and abilities like Regenerator, and prevents health recovery from berries and other items." },
    :SPIKEARMOR => { :name => "Spike Armor", :pif => false, :short => "30% chance to bleed on contact. Also works on offense.", :full => "Spike Armor has a 30% chance to inflict bleeding on contact moves, both when attacking and being attacked. Bleeding causes 1/16 max HP damage per turn, prevents healing, and negates the effects of stat stages. Rock and Ghost types are immune to bleeding." },
    :TERMINALVELOCITY => { :name => "Terminal Velocity", :pif => false, :short => "Special moves use 20% of its Speed stat additionally.", :full => "Adds 20% of the user's Speed stat to damage when using non-contact moves. Choice Scarf does not affect this ability." },
    :ARMORTAIL => { :name => "Armor Tail", :pif => false, :short => "Protects itself and ally from priority moves.", :full => "Prevents the user and its ally from being targeted by priority moves with priority higher than 0." },
    :FIRESCALES => { :name => "Fire Scales", :pif => false, :short => "Halves damage taken by Special moves. Does NOT double SpDef.", :full => "Halves all incoming special attack damage. Multiplicative with other sources of damage reduction." },
    :WATCHYOURSTEP => { :name => "Watch Your Step", :pif => false, :short => "Spreads two layers of Spikes on switch-in.", :full => "Spreads two layers of Spikes on switch-in." },
    :SHARPEDGES => { :name => "Sharp Edges", :pif => false, :short => "Enemies lose 1/6 of max HP if they hit user with contact move.", :full => "Damages attackers using contact moves for 1/6 of their max HP. Activates on every hit for multihitting moves." },
    :GOODASGOLD => { :name => "Good As Gold", :pif => false, :short => "Immune to all Status moves, unless whole field is affected.", :full => "Good As Gold grants immunity to all status moves that directly target this Pokemon. Remains vulnerable to status moves that affect the entire field, such as Haze." },
    :DEADPOWER => { :name => "Dead Power", :pif => false, :short => "1.5x Attack boost. 20% chance to curse on contact moves.", :full => "Boosts the user's Attack stat by 50% and 20% chance to inflict curse on contact moves. Curse inflicts 25% max HP damage per turn until the cursed Pokemon switches out or faints. The Attack boost is multiplicative with other damage boosts." },
    :DESERTSPIRIT => { :name => "Desert Spirit", :pif => false, :short => "Summons sand on entry. Ground moves hit airborne in sand.", :full => "Summons sandstorm on entry, lasting 8 turns (12 with Smooth Stone). During sandstorm, the user's Ground-type moves bypass immunity and hit airborne Pokemon with normal effectiveness. The user is immune to sandstorm damage." },
    :CONTEMPT => { :name => "Contempt", :pif => false, :short => "Unaware + Defiant.", :full => "Ignores all the foes' stat stage changes during damage calculations. When the user has their stats lowered by another Pokemon, they raise their Attack by 2 stages." },
    :REJECTION => { :name => "Rejection", :pif => false, :short => "Applies Quash on switch-in.", :full => "Casts Quash on entry. Quash nullifies most Speed altering effects, including Tailwind, Trick Room, positive priority, Speed stat raises, etc. Negative priority works as normal. Lasts 5 turns." },
    :BALLOONBOMB => { :name => "Balloon Bomb", :pif => false, :short => "Aftermath + Inflatable", :full => "Uses a 100 BP Explosion or Outburst (whichever is higher) when knocked out. Using explosion moves will always Flinch the target. When hit by any Fire or Flying moves, boost Defense and Special Defense by one stage each. Activates on each hit of a multihit move. Boost applies after the hit lands." },
    :PHOBIA => { :name => "Phobia", :pif => false, :short => "30% chance to Fear on contact. Also works on offense.", :full => "Has a 30% chance to inflict Fear on contact moves, both when attacking and being attacked. Fear traps the target for 2 turns and they take 50% more damage. If forced out by moves like Whirlwind, the target loses Fear." },
    :SHINYLIGHTNING => { :name => "Shiny Lightning", :pif => false, :short => "Grants a 1.2x accuracy boost. Thunder never misses.", :full => "Boosts the user's accuracy by 1.2x, and Thunder never misses." },
    :BATTLEAURA => { :name => "Battle Aura", :pif => false, :short => "Boosts each battler's crit rate by +2.", :full => "Increases each Pokemon's critical hit stage by +2. Includes both allies and opponents." },
    :ARCFLASH => { :name => "Arc Flash", :pif => false, :short => "50% chance to burn when hit or paralyze when dealing damage.", :full => "When the user attacks, it has a 50% chance to paralyze the target upon contact. When receiving damage, it has a 50% chance to burn the attacker." },
    :NOTURNINGBACK => { :name => "No Turning Back", :pif => false, :short => "Boosts all stats but can't retreat when below 1/2 max HP.", :full => "When HP drops to half or below for the first time, all stats increase by one stage and the user becomes unable to switch out or flee. Normal ways to bypass this effects such as Eject Button or Shed Shell still allow switching out." },
    :FLUFFIEST => { :name => "Fluffiest", :pif => false, :short => "Quarters contact damage taken. 4x weak to Fire-type moves.", :full => "Reduces damage from contact moves by 75%. Fire-type moves to deal x4 damage to the user. Multiplicative with other forms of damage reduction." },
    :RESTRAININGORDER => { :name => "Restraining Order", :pif => false, :short => "Forces the attacker out when hit, once each switch-in.", :full => "When the user is hit by a contact move, they force the attacker to switch out to a random ally. Once per switch in." },
    :SHOCKINGMAW => { :name => "Shocking Maw", :pif => false, :short => "Strong Jaw + Shocking Jaws.", :full => "Boosts the power of biting and fang moves by 30% and they have a 50% chance to paralyze the target on hit." },
    :GLEAMEYES => { :name => "Gleam Eyes", :pif => false, :short => "Frisk + Scare.", :full => "Upon entering battle, reveals the opponents' items and prevents them from working for 2 turns; and the user drops the Special Attack stat of all opposing Pokemon by one stage. Does not prevent Mega Stones and other similar items from working." },
    :MEGABITE => { :name => "Megabite", :pif => false, :short => "Biting moves use SpAtk and deal 30% more damage.", :full => "Biting moves use the Special Attack (still targets enemy's Defense unless stated otherwise) and deal 30% more damage." },
    :DREAMSTATE => { :name => "Dream State", :pif => false, :short => "Immune to critical hits. Takes 20% less damage from attacks.", :full => "Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed." },
    :DREAMWHIMSY => { :name => "Dream Whimsy", :pif => false, :short => "Uses Yawn on switch-in.", :full => "Uses Yawn on switch in, targeting the opposing Pokemon. Yawn causes drowsiness that makes the target fall asleep at the end of the next turn. The sleep effect can be prevented by switching out." },
    :FLAMESHIELD => { :name => "Flame Shield", :pif => false, :short => "Takes 35% less damage from Super-effective moves.", :full => "Reduces damage from super-effective attacks by 35%. Multiplicative with other sources of damage reduction." },
    :WILDFIRE => { :name => "Wildfire", :pif => false, :short => "Attacks with Fire Spin on entry.", :full => "Uses Fire Spin upon switching into battle, a 50 BP Fire-type Special move that traps the opponent for 4-5 turns. The target takes 1/8 max HP damage each turn and cannot switch out until the trap ends." },
    :JUMPSCARE => { :name => "Jumpscare", :pif => false, :short => "Attacks with Astonish on first switch-in.", :full => "Uses Astonish on switch in, a 40 BP Ghost-type Physical move with +3 priority that always causes flinching. Once per battle." },
    :TRASHHEAP => { :name => "Trash Heap", :pif => false, :short => "Corrosion + Toxic Spill.", :full => "Poison-type moves become super effective against Steel-type Pokemon. Additionally, this Pokemon can inflict poison status on any type. Damages all non-Poison-type Pokemon by 1/8 HP each turn. Pokemon with Poison Heal recover instead. Disappears when the user leaves." },
    :TOTHEBONE => { :name => "To The Bone", :pif => false, :short => "Critical hits get a 1.5x boost and inflict bleeding.", :full => "Critical hits get a 1.5x boost and inflict bleeding." },
    :APESHIFT => { :name => "Ape Shift", :pif => false, :short => "Transforms below 50% HP, curing status and always critting.", :full => "Transforms the Pokemon when HP drops to 50% or below, automatically curing all status conditions after transformation. After transforming, all attacks become critical hits. Activates on entry, during battle, and at turn end." },
    :KNOWYOURPLACE => { :name => "Know Your Place", :pif => false, :short => "Contact moves make target move last for 5 turns.", :full => "Landing contact moves causes the target to always move last regardless of priority, speed, or other effects for 5 turns. Effect does not stack or refresh on already afflicted targets." },
    :ENERGYSIPHON => { :name => "Energy Siphon", :pif => false, :short => "Heals the user for 1/4 of the damage they deal.", :full => "Heals the user for 25% of all damage they deal to opponents. Healing occurs immediately after damage is dealt. Minimum healing of 1 HP." },
    :BALLOONBLITZ => { :name => "Balloon Blitz", :pif => false, :short => "Inflatable + Hyper Aggressive.", :full => "When hit by any Fire or Flying moves, boost Defense and Special Defense by one stage. Activates on each hit of a multihit move. Boost applies after the hit lands. All attacks hit twice. First hit deals 100%, while the second deals 25%. Each hit rolls secondary effects independently (except flinch)." },
    :ACIDICSLIME => { :name => "Acidic Slime", :pif => false, :short => "Corrosion + Poison STAB.", :full => "Poison-type moves become super effective against Steel-type Pokemon. Additionally, this Pokemon can inflict poison status on any type. Also gives STAB to Poison-type moves." },
    :ROSEGARDEN => { :name => "Rose Garden", :pif => false, :short => "Spreads two layers of Toxic Spikes on switch-in.", :full => "Spreads two layers of Toxic Spikes on the opponent's side on entry. Any non-Poison or Steel-type grounded enemy that switches in will be badly poisoned." },
    :CONJUREROFDECEIT => { :name => "Conjurer Of Deceit", :pif => false, :short => "Magic Guard + Magic Bounce", :full => "Grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil. Reflects most status moves back to the user before they can take effect. Reflected moves target the original user. Does not reflect moves that were already reflected." },
    :FLAMECOAT => { :name => "Flame Coat", :pif => false, :short => "Non-Fire-types take 1/8 dmg every turn when on field.", :full => "Non-Fire-types take 1/8 dmg every turn when on field." },
    :VENOMCROWN => { :name => "Venom Crown", :pif => false, :short => "Poison Point + Mighty Horn.", :full => "Has a 30% chance to inflict poison on contact moves, both when attacking and being attacked. Boosts the power of horn and drill-based attacks by 30%." },
    :BLIGHTSCALE => { :name => "Blight Scale", :pif => false, :short => "Multiscale + Poison Point", :full => "Reduces all incoming damage by 50% when the Pokemon is at max HP. Multiplicative with other sources of damage reduction. Has a 30% chance to inflict poison on contact moves, both when attacking and being attacked." },
    :GLACIALRAGE => { :name => "Glacial Rage", :pif => false, :short => "Triggers 50 BP Blizzard after using an Ice-type move.", :full => "After using an Ice-type move, the user follows up with a 50 BP Blizzard (Ice, 85% accuracy, hits both opponents, 20% frostbite chance. Weather-based)." },
    :IMMOVABLEOBJECT => { :name => "Immovable Object", :pif => false, :short => "Impenetrable + Sturdy.", :full => "Grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil. When at full HP, this Pokemon will survive any single attack with at least 1 HP remaining." },
    :METALLICJAWS => { :name => "Metallic Jaws", :pif => false, :short => "Metallic + Primal Maw.", :full => "Upon entering battle, adds Steel to the user's current typing. Retains Steel typing even upon losing the ability, going away only when switching out. all biting moves to hit twice. First hit deals 100% damage, second hit deals 40%. Each hit rolls secondary effects independently (except flinch)." },
    :SEPIALENS => { :name => "Sepia Lens", :pif => false, :short => "Tinted Lens + Sand Guard.", :full => "Combines Tinted Lens and Sand Guard. Doubles damage when attacking with not very effective moves. During sandstorm, blocks priority moves from opponents and halves damage from special attacks. Also grants immunity to sandstorm damage like other Ground-types." },
    :MALODOR => { :name => "Malodor", :pif => false, :short => "Suppresses attacker's abilities on contact.", :full => "When hit by a contact move, the user suppresses the attacker's ability and innates until they switch out." },
    :DRAKEOFRAGE => { :name => "Drake Of Rage", :pif => false, :short => "Tinted Lens + Rampage", :full => "Doubles damage when attacking into resistances. If a move would be resisted (0.5x damage or less), the damage is multiplied by 2x. Eliminates recharge turns when the user successfully KOs an opponent with a direct attack." },
    :OMINOUSSHROUD => { :name => "Ominous Shroud", :pif => false, :short => "Phantom + Shadow Shield.", :full => "Upon entering battle, adds Ghost to user's current typing. Retains Ghost typing even upon losing the ability, going away only when switching out. Halves damage from all attacks when at full HP. Multiplicative with other damage reduction sources." },
    :WONDERSCALE => { :name => "Wonder Scale", :pif => false, :short => "Shed Skin + Wonder Skin", :full => "At the end of each turn, there's a 30% chance for the user to cure status conditions afflicted on them. Immune to all damage boosting ability effects from opponents, other than Parental Bond and Multi-Headed." },
    :HASTEMAKESWASTE => { :name => "Haste Makes Waste", :pif => false, :short => "Stall + Analytic.", :full => "Reduces damage by 30% if the user has not moved yet. Multiplicative with other damage reduction sources. Works when the user switches in mid-turn. Boosts damage by 30% if the target has already moved this turn." },
    :HUNGRYMAWS => { :name => "Hungry Maws", :pif => false, :short => "Strong Jaw + Jaws of Carnage.", :full => "Bite and jaw moves are boosted by 30%. Restores 50% max HP when defeating foes with biting moves or 25% with other moves. Only activates when knocking out a target with a direct hit." },
    :EDGELORD => { :name => "Edgelord", :pif => false, :short => "First Keen Edge move each entry gets +1 priority. Resets on KO.", :full => "First Keen Edge move each entry gets +1 priority. Resets on KO." },
    :CRAVING => { :name => "Craving", :pif => false, :short => "Eat a random berry at the end of the turn.", :full => "Eats one of the following berries at end of turn: Sitrus, Liechi, Ganlon, Salac, Petaya, Apicot, Lansat, Starf, or a random pinch healing berry." },
    :BACKUPPOWER => { :name => "Backup Power", :pif => false, :short => "Revives at 25% HP once after fainting in Electric Terrain.", :full => "Revives at 25% HP once after fainting in Electric Terrain." },
    :MALEDICTION => { :name => "Malediction", :pif => false, :short => "Every attack has a 20% Bleed chance and 10% Curse chance.", :full => "Every attack has a 20% Bleed chance and 10% Curse chance." },
    :HYDRA => { :name => "Hydra", :pif => false, :short => "Multi-Headed + Hubris.", :full => "Boosts the user's Special Attack by one stage whenever it knocks out an opponent with a direct hit. Attack 2-3 times per move based on number of heads. 1.25x total for 2 heads, 1.35x total for 3 heads." },
    :DRAKELPHEAD => { :name => "Drakelp Head", :pif => false, :short => "First hit taken deals 35% less damage, then lowers Atk by -1.", :full => "First hit taken deals 35% less damage, then lowers Atk by -1." },
    :POLARITY => { :name => "Polarity", :pif => false, :short => "Increases the party's highest stat by 30%", :full => "Increases the party's highest stat by 30%" },
    :SUMOGUARD => { :name => "Sumo Guard", :pif => false, :short => "Juggernaut + Thick Fat.", :full => "Juggernaut boosts contact moves by adding 20% of the user's Defense stat to attack calculations. Prevents paralysis and immediately cures the status if inflicted on the user. Reduces damage received from Fire and Ice-type moves by 50%. Multiplicative with other sources of damage reduction.\n\nJuggernaut: Juggernaut boosts contact moves by adding 20% of the user's Defense stat to attack calculations. Prevents paralysis and immediately cures the status if inflicted on the user.\n\nThick Fat: Reduces damage received from Fire and Ice-type moves by 50%. Multiplicative with other sources of damage reduction." },
    :SUMOWRESTLER => { :name => "Sumo Wrestler", :pif => false, :short => "Uses 20BP Circle Throw at the end of each 2nd turn.", :full => "Uses 20BP Circle Throw at the end of each 2nd turn." },
    :COSMICWINGS => { :name => "Cosmic Wings", :pif => false, :short => "Flying moves become Fairy-type.", :full => "Flying moves become Fairy-type." },
    :COSMICDUST => { :name => "Cosmic Dust", :pif => false, :short => "Magic Guard + Cosmic Daze.", :full => "Grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil. Attacks against confused and enraged targets deal double damage. Additionally, confused and enraged enemies take twice as much damage when they hurt themselves from those statuses.\n\nMagic Guard: Grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil.\n\nCosmic Daze: Attacks against confused and enraged targets deal double damage. Additionally, confused and enraged enemies take twice as much damage when they hurt themselves from those statuses." },
    :GALEFORCEWINGS => { :name => "Galeforce Wings", :pif => false, :short => "Flying-type moves get +1 priority.", :full => "Flying-type moves get +1 priority." },
    :TUMMYACHE => { :name => "Tummyache", :pif => false, :short => "Thick Fat + Corrosion.", :full => "Reduces damage received from Fire and Ice-type moves by 50%. Multiplicative with other sources of damage reduction. Poison-type moves become super effective against Steel-type Pokemon. Additionally, this Pokemon can inflict poison status on any type.\n\nThick Fat: Reduces damage received from Fire and Ice-type moves by 50%. Multiplicative with other sources of damage reduction.\n\nCorrosion: Poison-type moves become super effective against Steel-type Pokemon. Additionally, this Pokemon can inflict poison status on any type." },
    :CHESTNUTSHIELD => { :name => "Chestnut Shield", :pif => false, :short => "Impenetrable + Bulletproof", :full => "Impenetrable grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil. Provides immunity to ball, bomb, and projectile moves. Includes Acid Spray, Rock Wrecker, Pollen Puff, and Barrage.\n\nImpenetrable: Impenetrable grants immunity to all non-attack damage sources including entry hazards, weather damage, status conditions, and recoil.\n\nBulletproof: Provides immunity to ball, bomb, and projectile moves. Includes Acid Spray, Rock Wrecker, Pollen Puff, and Barrage." },
    :CHESTNUTAXE => { :name => "Chestnut Axe", :pif => false, :short => "Keen Edge + Grass moves become Keen Edge boosted.", :full => "Keen Edge + Grass moves become Keen Edge boosted." },
    :GIANTSHURIKEN => { :name => "Giant Shuriken", :pif => false, :short => "Water Shuriken hits once with 100BP and +1 crit.", :full => "Water Shuriken hits once with 100BP and +1 crit." },
    :WITCHBROOM => { :name => "Witch Broom", :pif => false, :short => "Hyper Aggressive + Hover.", :full => "Makes all attacks hit twice in succession. The first hit deals 100%, while the second hit deals 25%. Each hit rolls secondary effects independently (except flinch). Upon entering battle, adds Psychic to the user's current typing. Retains Psychic typing even upon losing the ability, going away only when switching out. The user is immune to Ground-type moves and other ground effects such as Spikes and terrains.\n\nHyper Aggressive: Makes all attacks hit twice in succession. The first hit deals 100%, while the second hit deals 25%. Each hit rolls secondary effects independently (except flinch).\n\nHover: Upon entering battle, adds Psychic to the user's current typing. Retains Psychic typing even upon losing the ability, going away only when switching out. The user is immune to Ground-type moves and other ground effects such as Spikes and terrains." },
    :ANGELICWINGS => { :name => "Angelic Wings", :pif => false, :short => "Prism Scales + Imposing Wings.", :full => "Prism Scales reduces damage from all Special attacks by 30%. Stacks multiplicatively with other damage reduction sources. Boosts the power of all wing, wind, and air-based moves by 30%. The user is immune to Ground-type moves and other ground effects such as Spikes or terrains, and boosts the power of Flying-type moves by 25%.\n\nPrism Scales: Prism Scales reduces damage from all Special attacks by 30%. Stacks multiplicatively with other damage reduction sources.\n\nImposing Wings: Boosts the power of all wing, wind, and air-based moves by 30%. The user is immune to Ground-type moves and other ground effects such as Spikes or terrains, and boosts the power of Flying-type moves by 25%." },
    :WRESTLESHOWMAN => { :name => "Wrestle Showman", :pif => false, :short => "Flying Press gains +10BP and inflicts Taunt.", :full => "Flying Press gains +10BP and inflicts Taunt." },
    :LUCHALIBRE => { :name => "Lucha Libre", :pif => false, :short => "Dazzling + Defiant.", :full => "Dazzling blocks all priority moves from opponents targeting the user or allies. When the user has their stats lowered by another Pokemon, they raise their Attack by 2 stages.\n\nDazzling: Dazzling blocks all priority moves from opponents targeting the user or allies.\n\nDefiant: When the user has their stats lowered by another Pokemon, they raise their Attack by 2 stages." },
    :CHANDELIER => { :name => "Chandelier", :pif => false, :short => "Illuminate + Pyromancy.", :full => "Boosts the user's accuracy by 1.2x. Removes Ghost-type from the target when landing an attack. Pyromancy multiplies the burn chance of all moves by 5x. Does not interact with Flame Body.\n\nIlluminate: Boosts the user's accuracy by 1.2x. Removes Ghost-type from the target when landing an attack.\n\nPyromancy: Pyromancy multiplies the burn chance of all moves by 5x. Does not interact with Flame Body." },
    :FOGGYEYE => { :name => "Foggy Eye", :pif => false, :short => "While in Fog, boost Ghost moves by 50% and resist Ghost moves.", :full => "While in Fog, boost Ghost moves by 50% and resist Ghost moves." },
    :TOXICSHELL => { :name => "Toxic Shell", :pif => false, :short => "Shell Armor + Poison Point.", :full => "Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed. Has a 30% chance to inflict poison on contact moves, both when attacking and being attacked.\n\nShell Armor: Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed.\n\nPoison Point: Has a 30% chance to inflict poison on contact moves, both when attacking and being attacked." },
    :BREAKITDOWN => { :name => "Break it Down", :pif => false, :short => "Triggers 20BP Rapid Spin after using a damaging move.", :full => "Triggers 20BP Rapid Spin after using a damaging move." },
    :TALONTRAP => { :name => "Talon Trap", :pif => false, :short => "50% chance to trap on contact. 100% if entered this turn.", :full => "Has a 50% chance to trap the foe when making contact, on either offense or defense, as if by the move Snap Trap. If the user is switching in or gained the ability this turn, such as by mega evolving, the chance is increased to 100%." },
    :BACKSTREETBOY => { :name => "Backstreet Boy", :pif => false, :short => "Striker + Kicking moves are Dance moves and vise-versa.", :full => "Striker + Kicking moves are Dance moves and vise-versa." },
    :BACKFLIP => { :name => "Backflip", :pif => false, :short => "Triggers 50BP Chip Away after using a Dance move.", :full => "Triggers 50BP Chip Away after using a Dance move." },
    :CRUSHINGJAW => { :name => "Crushing Jaw", :pif => false, :short => "Strong Jaw + Biting moves have a 50% chance to lower defense.", :full => "Strong Jaw + Biting moves have a 50% chance to lower defense." },
    :HOLLOWICEZONE => { :name => "Hollow Ice Zone", :pif => false, :short => "Ice-type moves apply Ice Statue and then make the user switch.", :full => "The user's Ice-type moves apply the Ice Statue status to the target, making them Ice-type with no resistances or frostbite immunity. If Ice Statue is applied the user switches." },
    :CRYOSTASIS => { :name => "Cryostasis", :pif => false, :short => "Cryomancy + Frostbite causes flinching.", :full => "Cryomancy + Frostbite causes flinching." },
    :OVERCAST => { :name => "Overcast", :pif => false, :short => "Low Visibility + Frosty Presence.", :full => "Summons Eerie Fog upon entry, lasting 8 turns (12 with Smoke Ball). Fog reduces stat buffs from non-Ghost/Psychic-types by 1 each turn, halves weather-based recovery, grants Ghost/Psychic-types +20% damage reduction from moves, and turns all Curses into the Ghost-type Curse. Uses Mist on entry.\n\nLow Visibility: Summons Eerie Fog upon entry, lasting 8 turns (12 with Smoke Ball). Fog reduces stat buffs from non-Ghost/Psychic-types by 1 each turn, halves weather-based recovery, grants Ghost/Psychic-types +20% damage reduction from moves, and turns all Curses into the Ghost-type Curse.\n\nFrosty Presence: Uses Mist on entry." },
    :FLOWERNECKLACE => { :name => "Flower Necklace", :pif => false, :short => "Boosts Special Defense by 50% in Grassy Terrain.", :full => "Boosts Special Defense by 50% in Grassy Terrain." },
    :MUCUSMEMBRANE => { :name => "Mucus Membrane", :pif => false, :short => "Takes 30% less damage from attacks + Gooey", :full => "Takes 30% less damage from attacks + Gooey" },
    :WATERBORNE => { :name => "Waterborne", :pif => false, :short => "Aquatic + Adaptability", :full => "Upon entering battle, adds Water to the user's current typing. Retains Water typing even upon losing the ability, going away only when switching out. Boosts STAB damage boost on moves from 1.5x to 2.0x damage.\n\nAquatic: Upon entering battle, adds Water to the user's current typing. Retains Water typing even upon losing the ability, going away only when switching out.\n\nAdaptability: Boosts STAB damage boost on moves from 1.5x to 2.0x damage." },
    :THUNDERCLOUDS => { :name => "Thunder Clouds", :pif => false, :short => "Triggers 35BP Tunderbolt after using a special move.", :full => "Triggers 35BP Tunderbolt after using a special move." },
    :SHATTEREDARMOR => { :name => "Shattered Armor", :pif => false, :short => "Battle Armor + Scrapyard.", :full => "Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed. Sets a layer of Spikes on the opponent's side when the user is successfully hit by a contact move. Each layer damages switching grounded Pokemon by 12.5%, 16.7%, or 25% of max HP for 1-3 layers respectively. Each hit of a multihitting attack sets a layer.\n\nBattle Armor: Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed.\n\nScrapyard: Sets a layer of Spikes on the opponent's side when the user is successfully hit by a contact move. Each layer damages switching grounded Pokemon by 12.5%, 16.7%, or 25% of max HP for 1-3 layers respectively. Each hit of a multihitting attack sets a layer." },
    :ACIDREFLUX => { :name => "Acid Reflux", :pif => false, :short => "Uses 20BP Acid when taking any damage.", :full => "Uses 20BP Acid when taking any damage." },
    :POWEROUTAGE => { :name => "Power Outage", :pif => false, :short => "Boosts first Electric attack by 2x but user loses Electric-type.", :full => "The first Electric Move will double in damage, but once used will lose its Electric typing." },
    :ELECTROBOOSTER => { :name => "Electro Booster", :pif => false, :short => "Uses Magnet Rise on entry.", :full => "Uses Magnet Rise on entry." },
    :CURRENTCRASH => { :name => "Current Crash", :pif => false, :short => "Reckless + Thundercall.", :full => "Increases the damage of moves that cause recoil by 20%. This bonus also applies when moves gain recoil through other means, such as madness or abilities. After using any Electric-type move, Thundercall automatically triggers a follow-up Smite attack at 20% power (24 base power). This physical Electric attack has an 80% accuracy, can paralyze targets (20% chance), and applies the Smack Down effect - grounding Flying-types.\n\nReckless: Increases the damage of moves that cause recoil by 20%. This bonus also applies when moves gain recoil through other means, such as madness or abilities.\n\nThundercall: After using any Electric-type move, Thundercall automatically triggers a follow-up Smite attack at 20% power (24 base power). This physical Electric attack has an 80% accuracy, can paralyze targets (20% chance), and applies the Smack Down effect - grounding Flying-types." },
    :DAREDEVIL => { :name => "Daredevil", :pif => false, :short => "Ups Attack by +1 when using recoil move. Halves recoil dmg.", :full => "Boosts Attack stat by +1 after using a move that causes recoil damage. Takes 1/2 recoil damage." },
    :SINISTERCLAWS => { :name => "Sinister Claws", :pif => false, :short => "Mystic Blades + Keen Edge moves lower SpDef.", :full => "Keen Edge attacks deal 1.3x damage and become special moves, using Special Attack and hitting Special Defense. They also lower the target's Special Defense by 1 stage (max once per turn per target)." },
    :DROIDEKA => { :name => "Droideka", :pif => false, :short => "Heatproof + Shell Armor.", :full => "Halves damage from Fire-type moves. Immune to burn damage and Attack drops from burn status. Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed.\n\nHeatproof: Halves damage from Fire-type moves. Immune to burn damage and Attack drops from burn status.\n\nShell Armor: Incoming damage is reduced by 20% (x0.8), multiplicative with other damage reduction. Additionally, critical hits are blocked, functioning as regular hits and not activating on-crit effects like To The Bone's bleed." },
    :WINDCHIMES => { :name => "Wind Chimes", :pif => false, :short => "Amplifier + uses 30BP Hyper Voice when hit.", :full => "Amplifier + uses 30BP Hyper Voice when hit." },
    :UNSTABLECORE => { :name => "Unstable Core", :pif => false, :short => "Power Core + Aftermath.", :full => "Adds 20% of Defense stat to physical attacks and 20% of Special Defense stat to special attacks when calculating damage. Uses a 100BP Explosion (if Attack is higher) or Outburst (if Special Attack is higher) when knocked out. Using explosion moves will always flinch the target.\n\nPower Core: Adds 20% of Defense stat to physical attacks and 20% of Special Defense stat to special attacks when calculating damage.\n\nAftermath: Uses a 100BP Explosion (if Attack is higher) or Outburst (if Special Attack is higher) when knocked out. Using explosion moves will always flinch the target." },
    :AURAARMOR => { :name => "Aura Armor", :pif => false, :short => "Takes 35% less damage from attacks.", :full => "Takes 35% less damage from attacks." },
    :DEFLECT => { :name => "Deflect", :pif => false, :short => "Uses 20 BP Vacuum Wave when hit. Takes 20% less damage.", :full => "Uses 20 BP Vacuum Wave when hit. Takes 20% less damage." },
    :REAPERSEMBARCE => { :name => "Reaper's Embarce", :pif => false, :short => "Tough Claws + Foul Energy.", :full => "Contact moves are boosted by 30%. Boosts Dark-type moves by 1.2x, or 1.5x when under 1/3 HP.\n\nTough Claws: Contact moves are boosted by 30%.\n\nFoul Energy: Boosts Dark-type moves by 1.2x, or 1.5x when under 1/3 HP." },
    :SLEEKSCALES => { :name => "Sleek Scales", :pif => false, :short => "The Pokémon uses +15% of its Speed when defending.", :full => "The Pokémon uses +15% of its Speed when defending." },
    :SANDTITAN => { :name => "Sand Titan", :pif => false, :short => "Juggernaut + Sand Stream", :full => "Adds 20% of the user's Defense stat to attack calculations for contact moves. Prevents paralysis, immediately curing it if inflicted on the user. Summons a sandstorm for 8 turns (12 with Smooth Rock) on entry. Immune to sandstorm damage." },
    :FAMILIABOND => { :name => "Familia Bond", :pif => false, :short => "Moves hit twice. 1st hit at 100% power, 2nd hit at 50%.", :full => "All attacks hit twice in succession. The first hit deals 100%, while the second hit deals 50%. Each hit rolls secondary effects independently (except flinch). Bypasses Fort Knox/Wonder Skin." },
    :MEGASOL => { :name => "Mega Sol", :pif => false, :short => "Chloroplast + Grassy Surge", :full => "Moves used by the user act as if the weather is harsh sunlight. Creates Grassy Terrain for 8 turns (12 with Terrain Extender) on entry." },
    :OVERCLOCK => { :name => "Overclock", :pif => false, :short => "Ground Shock + Overcharge", :full => "The user's Electric-type moves hit Ground types for not very effective damage instead of no effect, and hit Electric types for super effective damage instead of not very effective. The user can paralyze Electric types." },
  }
